+#define PY_SSIZE_T_CLEAN
+#include <Python.h>
+#include <stdint.h>
+#include <math.h>
+#include <string.h>
+#include <dlfcn.h>
+#include <glob.h>
+#include <numpy/arrayobject.h>
+
+typedef void (*dgeev_t)(char* jobvl, char* jobvr, int64_t* n, double* a,
+                        int64_t* lda, double* wr, double* wi, double* vl,
+                        int64_t* ldvl, double* vr, int64_t* ldvr,
+                        double* work, int64_t* lwork, int64_t* info);
+
+static dgeev_t dgeev_fn = NULL;
+
+static int load_dgeev_from_path(const char* path) {
+    void* handle = dlopen(path, RTLD_NOW | RTLD_GLOBAL);
+    if (!handle) return 0;
+    dgeev_t fn = (dgeev_t)dlsym(handle, "scipy_dgeev_64_");
+    if (fn) {
+        dgeev_fn = fn;
+        return 1;
+    }
+    return 0;
+}
+
+static void auto_init_dgeev(void) {
+    if (dgeev_fn) return;
+    const char* patterns[] = {
+        "/usr/local/lib/python3.13/site-packages/numpy.libs/libscipy_openblas*.so",
+        "/usr/local/lib/python3.*/site-packages/numpy.libs/libscipy_openblas*.so",
+        NULL
+    };
+    for (int i = 0; patterns[i] != NULL; i++) {
+        glob_t globbuf;
+        if (glob(patterns[i], 0, NULL, &globbuf) == 0) {
+            for (size_t j = 0; j < globbuf.gl_pathc; j++) {
+                if (load_dgeev_from_path(globbuf.gl_pathv[j])) {
+                    globfree(&globbuf);
+                    return;
+                }
+            }
+            globfree(&globbuf);
+        }
+    }
+}
+
+static PyObject* init_lib(PyObject* self, PyObject* args) {
+    const char* path;
+    if (!PyArg_ParseTuple(args, "s", &path)) return NULL;
