+py::tuple solve_matrix(const MatType& mat, int n) {
+    Eigen::EigenSolver<MatType> es(mat);
+    const auto& evals = es.eigenvalues();
+    const auto& evecs = es.eigenvectors();
+
+    int best_idx = 0;
+    double max_mag_sq = std::norm(evals(0));
+    bool all_real = (evals(0).imag() == 0.0);
+
+    for (int i = 1; i < n; ++i) {
+        double mag_sq = std::norm(evals(i));
+        if (mag_sq > max_mag_sq) {
+            max_mag_sq = mag_sq;
+            best_idx = i;
+        }
+        if (evals(i).imag() != 0.0) {
+            all_real = false;
+        }
+    }
+
+    if (all_real) {
+        py::array_t<double> res_vec(n);
+        double* ptr = res_vec.mutable_data();
+        for (int i = 0; i < n; ++i) {
+            ptr[i] = evecs(i, best_idx).real();
+        }
+        return py::make_tuple(py::cast(evals(best_idx).real()), res_vec);
+    } else {
+        py::array_t<std::complex<double>> res_vec(n);
+        std::complex<double>* ptr = res_vec.mutable_data();
+        for (int i = 0; i < n; ++i) {
+            ptr[i] = evecs(i, best_idx);
+        }
+        return py::make_tuple(py::cast(evals(best_idx)), res_vec);
+    }
+}
