+    if (arr.ndim() != 2 || arr.shape(0) != arr.shape(1)) {
+        throw std::invalid_argument("Input matrix must be 2D square");
+    }
+    int n = static_cast<int>(arr.shape(0));
+    if (n <= 0) {
+        throw std::invalid_argument("Matrix dimension must be positive");
