+import { type BaseRoot, rootSchemaScope } from "@ark/schema"
+import { type, type Type } from "arktype"
+import { jsonSchemaToType } from "./json.ts"
+
+export class JsonSchemaParseContext {
+	rootDefs: Record<string, unknown> | undefined
+	resolutions: Record<string, BaseRoot> = {}
+	resolving = new Set<string>()
+	aliases: Record<string, BaseRoot> = {}
+	$: any = rootSchemaScope
+
+	constructor(rootDefs?: Record<string, unknown>) {
+		this.rootDefs = rootDefs
+	}
+
+	resolveRef(defName: string): Type {
+		if (this.resolutions[defName]) {
+			return type(this.resolutions[defName])
+		}
+
+		if (this.resolving.has(defName)) {
+			if (!this.aliases[defName]) {
+				this.aliases[defName] = this.$.node(
+					"alias",
+					{
+						reference: `$${defName}`,
+						resolve: () => this.resolutions[defName]
+					},
+					{ prereduced: true }
+				)
+			}
+			return this.aliases[defName] as unknown as Type
+		}
+
+		this.resolving.add(defName)
+		const defSchema = this.rootDefs![defName]
+		const parsed = jsonSchemaToType(defSchema as any)
+		const n = parsed.internal
+
+		this.resolutions[defName] = n
+		this.$.resolutions[defName] = n
+		this.resolving.delete(defName)
+
+		return parsed
+	}
+}
+
+let currentParseContext: JsonSchemaParseContext | undefined
+
+export const getCurrentParseContext = ():
+	| JsonSchemaParseContext
+	| undefined => currentParseContext
+
+export const setCurrentParseContext = (
+	ctx: JsonSchemaParseContext | undefined
+): void => {
+	currentParseContext = ctx
+}
