@@ -0,0 +1,181 @@
+package expr_test
+
+import (
+	"strings"
+	"testing"
+
+	"github.com/expr-lang/expr"
+)
+
+func TestTryCatch(t *testing.T) {
+	tests := []struct {
+		name string
+		expr string
+		env  any
+		want any
+	}{
+		{
+			name: "try fallback on error",
+			expr: `try(1/0, "fallback")`,
+			want: "fallback",
+		},
+		{
+			name: "try success",
+			expr: `try(6*7, "fallback")`,
+			want: 42,
+		},
+		{
+			name: "try custom throw",
+			expr: `try(throw("boom"), "caught")`,
+			want: "caught",
+		},
+		{
+			name: "try block form without var",
+			expr: `try { 1/0 } catch { "handled" }`,
+			want: "handled",
+		},
+		{
+			name: "try block form with var",
+			expr: `try { throw("my error") } catch e { errtype(e) }`,
+			want: "custom",
+		},
+		{
+			name: "errtype nil",
+			expr: `errtype(nil)`,
+			want: "none",
+		},
+		{
+			name: "errtype index",
+			expr: `try { [1, 2][5] } catch e { errtype(e) }`,
+			want: "index",
+		},
+		{
+			name: "errtype conversion",
+			expr: `try { int("not_a_number") } catch e { errtype(e) }`,
+			want: "conversion",
+		},
+		{
+			name: "errtype type",
+			expr: `try { 1 + "foo" } catch e { errtype(e) }`,
+			want: "type",
+		},
+		{
+			name: "errtype nil pointer",
+			expr: `try { foo.bar } catch e { errtype(e) }`,
+			env:  map[string]any{"foo": nil},
+			want: "nil",
+		},
+		{
+			name: "catch substring filter match",
+			expr: `try { throw("specific failure occurred") } catch e is "specific failure" { "caught specific" } catch e { "caught other" }`,
+			want: "caught specific",
+		},
+		{
+			name: "catch substring filter fallback",
+			expr: `try { throw("something else") } catch e is "specific failure" { "caught specific" } catch e { "caught other" }`,
+			want: "caught other",
+		},
+		{
+			name: "finally on success",
+			expr: `try { 1 } catch { 2 } finally { 3 }`,
+			want: 1,
+		},
+		{
+			name: "finally on catch",
+			expr: `try { 1/0 } catch { 2 } finally { 3 }`,
+			want: 2,
+		},
+		{
+			name: "throw any value",
+			expr: `try { throw(12345) } catch e { e.Error() }`,
+			want: "12345",
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			got, err := expr.Eval(tt.expr, tt.env)
+			if err != nil {
+				t.Fatalf("unexpected error: %v", err)
+			}
+			if got != tt.want {
+				t.Fatalf("got %v (%T), want %v (%T)", got, got, tt.want, tt.want)
+			}
+		})
+	}
+}
+
+func TestFinallyOverride(t *testing.T) {
+	_, err := expr.Eval(`try { 1 } finally { throw("finally boom") }`, nil)
+	if err == nil {
+		t.Fatal("expected error from finally")
+	}
+	if !strings.Contains(err.Error(), "finally boom") {
+		t.Fatalf("expected 'finally boom', got %v", err)
+	}
+}
+
+func TestRetryMechanism(t *testing.T) {
+	// Retry within catch block
+	env := map[string]any{"count": 0}
+	src := `try {
+		throw("retry test")
+	} catch e {
+		retry
+	}`
+	program, err := expr.Compile(src, expr.Env(env))
+	if err != nil {
+		t.Fatalf("compile error: %v", err)
+	}
+	// After 3 retries (4 executions total), it should raise retry exhaustion
+	_, err = expr.Run(program, env)
+	if err == nil {
+		t.Fatal("expected retry exhaustion error")
+	}
+
+	// Verify retry exhaustion errtype is "retry"
+	exhaustionTest := `try {
+		try {
+			throw("fail")
+		} catch e {
+			retry
+		}
+	} catch outer {
+		errtype(outer)
+	}`
+	got, err := expr.Eval(exhaustionTest, nil)
+	if err != nil {
+		t.Fatalf("unexpected error: %v", err)
+	}
+	if got != "retry" {
+		t.Fatalf("expected 'retry', got %v", got)
+	}
+}
+
+func TestRetryOutsideCatch(t *testing.T) {
+	_, err := expr.Eval(`retry`, nil)
+	if err == nil {
