+package runtime
+
+import (
+	"fmt"
+	"reflect"
+	"strings"
+)
+
+type RuntimeError struct {
+	Type    string `json:"type"`
+	Message string `json:"message"`
+	Value   any    `json:"value"`
+}
+
+func (e *RuntimeError) Error() string {
+	return e.Message
+}
+
+func (e *RuntimeError) String() string {
+	return e.Message
+}
+
+// ErrType returns the classification of an error:
+// "index", "conversion", "type", "nil", "retry", "custom", or "none" (if nil).
+func ErrType(val any) string {
+	if isNil(val) {
+		return "none"
+	}
+
+	if re, ok := val.(*RuntimeError); ok {
+		if re == nil {
+			return "none"
+		}
+		if re.Type != "" {
+			return re.Type
+		}
+		return ClassifyMessage(re.Message)
+	}
+
+	if err, ok := val.(interface{ Unwrap() error }); ok {
+		if prev := err.Unwrap(); prev != nil {
+			if t := ErrType(prev); t != "custom" {
+				return t
+			}
+		}
+	}
+
+	msg := fmt.Sprintf("%v", val)
+	return ClassifyMessage(msg)
+}
+
+func isNil(val any) bool {
+	if val == nil {
+		return true
+	}
+	v := reflect.ValueOf(val)
+	switch v.Kind() {
+	case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map, reflect.Pointer, reflect.Slice:
+		return v.IsNil()
+	default:
+		return false
+	}
+}
+
+func ClassifyPanic(r any) *RuntimeError {
+	if re, ok := r.(*RuntimeError); ok {
+		return re
+	}
+	if err, ok := r.(interface{ Unwrap() error }); ok {
+		if re, ok := err.Unwrap().(*RuntimeError); ok {
+			return re
+		}
+	}
+	msg := fmt.Sprintf("%v", r)
+	t := ClassifyMessage(msg)
+	return &RuntimeError{
+		Type:    t,
+		Message: msg,
+		Value:   r,
+	}
+}
+
+func ClassifyMessage(msg string) string {
+	lower := strings.ToLower(msg)
+
+	// retry exhaustion errors
+	if strings.Contains(lower, "retry limit") || strings.Contains(lower, "retry exhaustion") || lower == "retry" {
+		return "retry"
+	}
+
+	// index out-of-range/bounds errors
+	if strings.Contains(lower, "index out of range") ||
+		strings.Contains(lower, "slice bounds out of range") ||
+		strings.Contains(lower, "bounds out of range") ||
+		strings.Contains(lower, "slice index out of range") ||
+		strings.Contains(lower, "out of range") ||
+		strings.Contains(lower, "out of bounds") {
+		return "index"
+	}
+
+	// nil-pointer/reference errors
+	if strings.Contains(lower, "nil pointer") ||
+		strings.Contains(lower, "nil dereference") ||
+		strings.Contains(lower, "invalid memory address") ||
+		strings.Contains(lower, "from <nil>") ||
+		strings.Contains(lower, "from nil") {
+		return "nil"
+	}
+
+	// conversion failures
+	if strings.Contains(lower, "cannot convert") ||
+		strings.Contains(lower, "conversion") ||
+		strings.Contains(lower, "invalid operation: int(") ||
+		strings.Contains(lower, "invalid operation: int64(") ||
+		strings.Contains(lower, "invalid operation: float(") ||
+		strings.Contains(lower, "invalid operation: bool(") ||
+		strings.Contains(lower, "invalid syntax") ||
+		strings.Contains(lower, "parsing") ||
+		strings.Contains(lower, "invalid duration") {
+		return "conversion"
+	}
+
+	// type-mismatch/assertion errors
+	if strings.Contains(lower, "interface conversion") ||
+		strings.Contains(lower, "mismatched types") ||
+		strings.Contains(lower, "type mismatch") ||
+		strings.Contains(lower, "type-mismatch") ||
+		strings.Contains(lower, "cannot fetch") ||
+		strings.Contains(lower, "cannot use") ||
+		strings.Contains(lower, "not defined on") ||
+		strings.Contains(lower, "operator not defined") ||
+		strings.Contains(lower, "invalid operation:") ||
+		strings.Contains(lower, "cannot slice") ||
+		strings.Contains(lower, "invalid argument for") ||
+		strings.Contains(lower, "cannot call non-function") ||
+		strings.Contains(lower, "negative shift count") {
+		return "type"
+	}
+
+	// all other errors including custom/throw
+	return "custom"
+}
