+package builtin
+
+import (
+	"fmt"
+	"strings"
+
+	"github.com/expr-lang/expr/file"
+)
+
+type CustomError struct {
+	Val any
+	Msg string
+}
+
+func (e *CustomError) Error() string {
+	return e.Msg
+}
+
+func (e *CustomError) String() string {
+	return e.Msg
+}
+
+type RetryExhaustedError struct {
+	Message string
+}
+
+func (e *RetryExhaustedError) Error() string {
+	if e.Message != "" {
+		return e.Message
+	}
+	return "retry limit exceeded"
+}
+
+func (e *RetryExhaustedError) String() string {
+	return e.Error()
+}
+
+func ErrType(err any) string {
+	if err == nil {
+		return "none"
+	}
+
+	if _, ok := err.(*RetryExhaustedError); ok {
+		return "retry"
+	}
+	if _, ok := err.(*CustomError); ok {
+		return "custom"
+	}
+
+	if fe, ok := err.(*file.Error); ok {
+		// If wrapped error is CustomError or RetryExhaustedError:
+		if fe.Prev != nil {
+			if _, ok := fe.Prev.(*RetryExhaustedError); ok {
+				return "retry"
+			}
+			if _, ok := fe.Prev.(*CustomError); ok {
+				return "custom"
+			}
+		}
+		if fe.Message != "" {
+			return classifyErrorMessage(fe.Message)
+		}
+	}
+
+	if e, ok := err.(error); ok {
+		return classifyErrorMessage(e.Error())
+	}
+
+	return classifyErrorMessage(fmt.Sprint(err))
+}
+
+func classifyErrorMessage(msg string) string {
+	msgLower := strings.ToLower(msg)
+
+	if strings.Contains(msgLower, "retry limit") || strings.Contains(msgLower, "retry exhaustion") {
+		return "retry"
+	}
+
+	// Nil pointer / reference
+	if strings.Contains(msgLower, "nil pointer") ||
+		strings.Contains(msgLower, "nil reference") ||
+		strings.Contains(msgLower, "nil dereference") ||
+		strings.Contains(msgLower, "invalid memory address") ||
+		strings.Contains(msgLower, "from nil") ||
+		strings.Contains(msgLower, "on nil") {
+		return "nil"
+	}
+
+	// Index out-of-range / bounds
+	if strings.Contains(msgLower, "out of range") ||
+		strings.Contains(msgLower, "out of bounds") ||
+		strings.Contains(msgLower, "slice index") ||
+		strings.Contains(msgLower, "index out of") {
+		return "index"
+	}
+
+	// Type mismatch / assertion
+	if strings.Contains(msgLower, "interface conversion:") ||
+		strings.Contains(msgLower, "type mismatch") ||
+		strings.Contains(msgLower, "type-mismatch") ||
+		strings.Contains(msgLower, "type assertion") ||
+		strings.Contains(msgLower, "mismatched types") ||
+		strings.Contains(msgLower, "type of argument") ||
+		(strings.Contains(msgLower, "cannot use") && strings.Contains(msgLower, "as type")) {
+		return "type"
+	}
+
+	// Type-conversion failures
+	if strings.Contains(msgLower, "invalid operation: int") ||
+		strings.Contains(msgLower, "invalid operation: float") ||
+		strings.Contains(msgLower, "invalid operation: uint") ||
+		strings.Contains(msgLower, "invalid operation: string") ||
+		strings.Contains(msgLower, "invalid syntax") ||
+		strings.Contains(msgLower, "cannot convert") ||
+		strings.Contains(msgLower, "conversion") ||
+		strings.Contains(msgLower, "cannot cast") ||
+		strings.Contains(msgLower, "strconv.") ||
+		strings.Contains(msgLower, "parsing ") ||
+		strings.Contains(msgLower, "invalid argument for int") ||
+		strings.Contains(msgLower, "invalid argument for float") ||
+		strings.Contains(msgLower, "invalid argument for date") ||
+		strings.Contains(msgLower, "invalid argument for duration") {
