@@ -0,0 +1,113 @@
+package expr_test
+
+import (
+	"testing"
+
+	"github.com/expr-lang/expr"
+	"github.com/expr-lang/expr/internal/testify/require"
+)
+
+func TestErrorHandling(t *testing.T) {
+	t.Run("try function form", func(t *testing.T) {
+		out, err := expr.Eval(`try(1/0, "fallback")`, nil)
+		require.NoError(t, err)
+		require.Equal(t, "fallback", out)
+
+		out, err = expr.Eval(`try(6*7, "fallback")`, nil)
+		require.NoError(t, err)
+		require.Equal(t, 42, out)
+
+		out, err = expr.Eval(`try(throw("boom"), "caught")`, nil)
+		require.NoError(t, err)
+		require.Equal(t, "caught", out)
+
+		_, err = expr.Eval(`try(1)`, nil)
+		require.Error(t, err)
+
+		_, err = expr.Eval(`try(1, 2, 3)`, nil)
+		require.Error(t, err)
+	})
+
+	t.Run("try block form without variable", func(t *testing.T) {
+		out, err := expr.Eval(`try { 1/0 } catch { "handled" }`, nil)
+		require.NoError(t, err)
+		require.Equal(t, "handled", out)
+
+		out, err = expr.Eval(`try { 10 + 5 } catch { 0 }`, nil)
+		require.NoError(t, err)
+		require.Equal(t, 15, out)
+	})
+
+	t.Run("try block with error binding", func(t *testing.T) {
+		out, err := expr.Eval(`try { throw("boom") } catch e { errtype(e) }`, nil)
+		require.NoError(t, err)
+		require.Equal(t, "custom", out)
+	})
+
+	t.Run("catch with substring pattern", func(t *testing.T) {
+		out, err := expr.Eval(`try { throw("something fatal occurred") } catch e is "fatal" { "caught fatal" } catch e { "caught other" }`, nil)
+		require.NoError(t, err)
+		require.Equal(t, "caught fatal", out)
+
+		out, err = expr.Eval(`try { throw("minor issue") } catch e is "fatal" { "caught fatal" } catch e { "caught other" }`, nil)
+		require.NoError(t, err)
+		require.Equal(t, "caught other", out)
+	})
+
+	t.Run("finally execution and result overriding", func(t *testing.T) {
+		out, err := expr.Eval(`try { 1 } catch { 2 } finally { 3 }`, nil)
+		require.NoError(t, err)
+		require.Equal(t, 1, out)
+
+		out, err = expr.Eval(`try { 1/0 } catch { 2 } finally { 3 }`, nil)
+		require.NoError(t, err)
+		require.Equal(t, 2, out)
+
+		_, err = expr.Eval(`try { 1 } finally { throw("finally boom") }`, nil)
+		require.Error(t, err)
+		require.Contains(t, err.Error(), "finally boom")
+
+		_, err = expr.Eval(`try { 1/0 } catch { 2 } finally { throw("finally override") }`, nil)
+		require.Error(t, err)
+		require.Contains(t, err.Error(), "finally override")
+	})
+
+	t.Run("retry inside and outside catch", func(t *testing.T) {
+		_, err := expr.Eval(`retry`, nil)
+		require.Error(t, err)
+
+		env := map[string]any{"count": 0}
+		// Retry limit of 3
+		out, err := expr.Eval(`
+			try {
+				try {
+					throw("fail")
+				} catch {
+					retry
+				}
+			} catch e {
+				errtype(e)
+			}
+		`, env)
+		require.NoError(t, err)
+		require.Equal(t, "retry", out)
+	})
+
+	t.Run("errtype classifications", func(t *testing.T) {
+		out, err := expr.Eval(`errtype(nil)`, nil)
+		require.NoError(t, err)
+		require.Equal(t, "none", out)
+
+		out, err = expr.Eval(`try { [1, 2][5] } catch e { errtype(e) }`, nil)
+		require.NoError(t, err)
+		require.Equal(t, "index", out)
+
+		out, err = expr.Eval(`try { int("notanumber") } catch e { errtype(e) }`, nil)
+		require.NoError(t, err)
+		require.Equal(t, "conversion", out)
+
+		out, err = expr.Eval(`try { throw("custom error") } catch e { errtype(e) }`, nil)
+		require.NoError(t, err)
+		require.Equal(t, "custom", out)
+	})
+}
