+func (p *Parser) parseTryCatch(token Token) Node {
+	p.expect(Bracket, "{")
+	body := p.parseSequenceExpression()
+	p.expect(Bracket, "}")
+
+	var catches []CatchClause
+	for (p.current.Is(Identifier, "catch") || p.current.Is(Operator, "catch")) && p.err == nil {
+		p.next() // consume "catch"
+		var clause CatchClause
+		if p.current.Kind == Identifier && p.current.Value != "is" && !p.current.Is(Bracket, "{") {
+			clause.Var = p.current.Value
+			p.next()
+		}
+		if p.current.Is(Identifier, "is") || p.current.Is(Operator, "is") {
+			p.next()
+			if p.current.Kind != String {
+				p.error("expected string after is")
+				return nil
+			}
+			clause.HasPattern = true
+			clause.Pattern = p.current.Value
+			p.next()
+		}
+		p.expect(Bracket, "{")
+		clause.Handler = p.parseSequenceExpression()
+		p.expect(Bracket, "}")
+		catches = append(catches, clause)
+	}
+
+	var finally Node
+	if (p.current.Is(Identifier, "finally") || p.current.Is(Operator, "finally")) && p.err == nil {
+		p.next() // consume "finally"
+		p.expect(Bracket, "{")
+		finally = p.parseSequenceExpression()
+		p.expect(Bracket, "}")
+	}
+
+	if len(catches) == 0 && finally == nil {
+		p.error("expected catch or finally after try")
+		return nil
+	}
+
+	node := p.createNode(&TryNode{
+		Body:    body,
+		Catches: catches,
+		Finally: finally,
+	}, token.Location)
+	return node
+}
