@@ -0,0 +1,169 @@
+package expr_test
+
+import (
+	"testing"
+
+	"github.com/expr-lang/expr"
+	"github.com/expr-lang/expr/internal/testify/require"
+)
+
+func TestTry_FuncForm(t *testing.T) {
+	out, err := expr.Eval(`try(1/0, "fallback")`, nil)
+	require.NoError(t, err)
+	require.Equal(t, "fallback", out)
+
+	out, err = expr.Eval(`try(6*7, "fallback")`, nil)
+	require.NoError(t, err)
+	require.Equal(t, 42, out)
+
+	out, err = expr.Eval(`try(throw("boom"), "caught")`, nil)
+	require.NoError(t, err)
+	require.Equal(t, "caught", out)
+
+	_, err = expr.Eval(`try(1)`, nil)
+	require.Error(t, err)
+
+	_, err = expr.Eval(`try(1, 2, 3)`, nil)
+	require.Error(t, err)
+}
+
+func TestTryCatch_BlockForm(t *testing.T) {
+	out, err := expr.Eval(`try { 1/0 } catch { "handled" }`, nil)
+	require.NoError(t, err)
+	require.Equal(t, "handled", out)
+
+	out, err = expr.Eval(`try { throw("boom") } catch e { errtype(e) }`, nil)
+	require.NoError(t, err)
+	require.Equal(t, "custom", out)
+
+	out, err = expr.Eval(`try { 40 + 2 } catch e { "error" }`, nil)
+	require.NoError(t, err)
+	require.Equal(t, 42, out)
+}
+
+func TestCatch_Filter(t *testing.T) {
+	src := `
+		try {
+			throw("disk full error")
+		} catch e is "network" {
+			"network error"
+		} catch e is "disk" {
+			"disk error"
+		} catch {
+			"unknown"
+		}
+	`
+	out, err := expr.Eval(src, nil)
+	require.NoError(t, err)
+	require.Equal(t, "disk error", out)
+}
+
+func TestFinally(t *testing.T) {
+	// Finally executes on success
+	out, err := expr.Eval(`try { 1 } catch { 2 } finally { 3 }`, nil)
+	require.NoError(t, err)
+	require.Equal(t, 1, out)
+
+	// Finally executes on catch
+	out, err = expr.Eval(`try { throw("err") } catch { 2 } finally { 3 }`, nil)
+	require.NoError(t, err)
+	require.Equal(t, 2, out)
+
+	// Finally error propagates over prior success
+	_, err = expr.Eval(`try { 1 } finally { throw("finally boom") }`, nil)
+	require.Error(t, err)
+	require.Contains(t, err.Error(), "finally boom")
+
+	// Finally error propagates over prior catch error
+	_, err = expr.Eval(`try { throw("try boom") } catch { 2 } finally { throw("finally boom") }`, nil)
+	require.Error(t, err)
+	require.Contains(t, err.Error(), "finally boom")
+}
+
+func TestThrow(t *testing.T) {
+	_, err := expr.Eval(`throw("my error")`, nil)
+	require.Error(t, err)
+	require.Contains(t, err.Error(), "my error")
+
+	_, err = expr.Eval(`throw(123)`, nil)
+	require.Error(t, err)
+	require.Contains(t, err.Error(), "123")
+
+	_, err = expr.Eval(`throw()`, nil)
+	require.Error(t, err)
+
+	_, err = expr.Eval(`throw(1, 2)`, nil)
+	require.Error(t, err)
+}
+
+func TestRetry(t *testing.T) {
+	// Retry outside catch errors
+	_, err := expr.Eval(`retry`, nil)
+	require.Error(t, err)
+
+	// Retry exhaustion after 3 retries
+	env := map[string]any{
+		"count": 0,
+	}
+	src := `
+		try {
+			throw("fail")
+		} catch {
+			retry
+		}
+	`
+	_, err = expr.Eval(src, env)
+	require.Error(t, err)
+	require.Contains(t, err.Error(), "retry limit exceeded")
+
+	// Classifying retry exhaustion
+	srcClassify := `
+		try {
+			try {
+				throw("fail")
+			} catch {
+				retry
+			}
+		} catch e {
+			errtype(e)
+		}
+	`
+	out, err := expr.Eval(srcClassify, env)
+	require.NoError(t, err)
+	require.Equal(t, "retry", out)
+}
+
+func TestErrType(t *testing.T) {
+	// None
+	out, err := expr.Eval(`errtype(nil)`, nil)
+	require.NoError(t, err)
+	require.Equal(t, "none", out)
+
+	// Custom
+	out, err = expr.Eval(`try { throw("custom error") } catch e { errtype(e) }`, nil)
+	require.NoError(t, err)
+	require.Equal(t, "custom", out)
+
+	// Index
+	out, err = expr.Eval(`try { [1, 2, 3][10] } catch e { errtype(e) }`, nil)
+	require.NoError(t, err)
