@@ -0,0 +1,177 @@
+package runtime
+
+import (
+	"fmt"
+	"strings"
+)
+
+type CustomError struct {
+	Value   any
+	Message string
+}
+
+func (e *CustomError) Error() string {
+	return e.Message
+}
+
+func (e *CustomError) String() string {
+	return e.Message
+}
+
+type RetryExhaustedError struct {
+	Message string
+}
+
+func (e *RetryExhaustedError) Error() string {
+	if e.Message != "" {
+		return e.Message
+	}
+	return "retry limit exceeded"
+}
+
+func (e *RetryExhaustedError) String() string {
+	return e.Error()
+}
+
+type RuntimeError struct {
+	Message string `expr:"message"`
+	Type    string `expr:"type"`
+	Value   any    `expr:"value"`
+	Err     error  `expr:"-"`
+}
+
+func (e *RuntimeError) Error() string {
+	return e.Message
+}
+
+func (e *RuntimeError) String() string {
+	return e.Message
+}
+
+func ClassifyError(val any) string {
+	if val == nil {
+		return "none"
+	}
+
+	if re, ok := val.(*RuntimeError); ok {
+		if re.Type != "" {
+			return re.Type
+		}
+		if re.Err != nil {
+			val = re.Err
+		} else {
+			val = re.Message
+		}
+	}
+
+	if _, ok := val.(*RetryExhaustedError); ok {
+		return "retry"
+	}
+
+	if _, ok := val.(*CustomError); ok {
+		return "custom"
+	}
+
+	var msg string
+	switch v := val.(type) {
+	case error:
+		msg = v.Error()
+	case string:
+		msg = v
+	default:
+		msg = fmt.Sprintf("%v", v)
+	}
+
+	msgLower := strings.ToLower(msg)
+
+	if strings.Contains(msgLower, "retry limit") ||
+		strings.Contains(msgLower, "retry exhaustion") ||
+		strings.Contains(msgLower, "retry exhausted") {
+		return "retry"
+	}
+
+	// 1. Index: out-of-range/bounds errors
+	if strings.Contains(msgLower, "out of range") ||
+		strings.Contains(msgLower, "bounds out of range") ||
+		strings.Contains(msgLower, "index out of range") ||
+		strings.Contains(msgLower, "slice bounds out of range") {
+		return "index"
+	}
+
+	// 2. Conversion: type-conversion failures
+	if strings.Contains(msgLower, "invalid operation: int(") ||
+		strings.Contains(msgLower, "invalid operation: int64(") ||
+		strings.Contains(msgLower, "invalid operation: float(") ||
+		strings.Contains(msgLower, "invalid operation: bool(") ||
+		strings.Contains(msgLower, "invalid syntax") ||
+		strings.Contains(msgLower, "cannot convert") ||
+		strings.Contains(msgLower, "conversion") ||
+		strings.Contains(msgLower, "failed to parse") ||
+		strings.Contains(msgLower, "parsing \"") {
+		return "conversion"
+	}
+
+	// 3. Nil: nil-pointer/reference errors
+	if strings.Contains(msgLower, "nil pointer") ||
+		strings.Contains(msgLower, "nil-pointer") ||
+		strings.Contains(msgLower, "invalid memory address or nil pointer dereference") ||
+		strings.Contains(msgLower, "dereference of nil") ||
+		strings.Contains(msgLower, "from nil") ||
+		strings.Contains(msgLower, "<nil>") ||
+		strings.Contains(msgLower, "is nil") {
+		return "nil"
+	}
+
+	// 4. Type: type-mismatch/assertion errors
+	if strings.Contains(msgLower, "type mismatch") ||
+		strings.Contains(msgLower, "interface conversion") ||
+		strings.Contains(msgLower, "invalid operation:") ||
+		strings.Contains(msgLower, "invalid argument for len") ||
+		strings.Contains(msgLower, "operator \"in\" not defined on") ||
+		strings.Contains(msgLower, "cannot use") ||
+		strings.Contains(msgLower, "cannot cast") ||
+		strings.Contains(msgLower, "expected type") ||
+		strings.Contains(msgLower, "type error") {
+		return "type"
+	}
+
+	// 5. Custom: all other errors including those from throw
+	return "custom"
+}
+
+func ToRuntimeError(r any) *RuntimeError {
+	if re, ok := r.(*RuntimeError); ok {
+		return re
+	}
+	if ce, ok := r.(*CustomError); ok {
+		return &RuntimeError{
+			Message: ce.Message,
+			Type:    "custom",
+			Value:   ce.Value,
+			Err:     ce,
+		}
+	}
+	if ree, ok := r.(*RetryExhaustedError); ok {
+		return &RuntimeError{
+			Message: ree.Error(),
+			Type:    "retry",
+			Err:     ree,
+		}
+	}
+	var msg string
+	var err error
+	if e, ok := r.(error); ok {
+		err = e
+		msg = e.Error()
+	} else {
+		msg = fmt.Sprintf("%v", r)
+		err = fmt.Errorf("%v", r)
+	}
+	kind := ClassifyError(r)
+	return &RuntimeError{
+		Message: msg,
+		Type:    kind,
+		Value:   r,
+		Err:     err,
+	}
+}
