+package builtin
+
+import (
+	"fmt"
+	"strings"
+)
+
+type CustomError struct {
+	Message string
+	Value   any
+}
+
+func (e *CustomError) Error() string {
+	return e.Message
+}
+
+type RetryExhaustionError struct {
+	Message string
+}
+
+func (e *RetryExhaustionError) Error() string {
+	return e.Message
+}
+
+type RuntimeError struct {
+	Message string
+	Type    string
+	Value   any
+	Err     error
+}
+
+func (e *RuntimeError) Error() string {
+	return e.Message
+}
+
+func (e *RuntimeError) String() string {
+	return e.Message
+}
+
+func NewRuntimeError(r any) *RuntimeError {
+	if re, ok := r.(*RuntimeError); ok {
+		return re
+	}
+	if ce, ok := r.(*CustomError); ok {
+		return &RuntimeError{
+			Message: ce.Message,
+			Type:    "custom",
+			Value:   ce.Value,
+			Err:     ce,
+		}
+	}
+	if ree, ok := r.(*RetryExhaustionError); ok {
+		return &RuntimeError{
+			Message: ree.Message,
+			Type:    "retry",
+			Value:   ree,
+			Err:     ree,
+		}
+	}
+	var msg string
+	var errVal error
+	if e, ok := r.(error); ok {
+		errVal = e
+		msg = e.Error()
+	} else {
+		msg = fmt.Sprint(r)
+	}
+	k := ClassifyErrorMessage(msg)
+	return &RuntimeError{
+		Message: msg,
+		Type:    k,
+		Value:   r,
+		Err:     errVal,
+	}
+}
+
+func ClassifyError(err any) string {
+	if err == nil {
+		return "none"
+	}
+	if re, ok := err.(*RuntimeError); ok {
+		return re.Type
+	}
+	if _, ok := err.(*CustomError); ok {
+		return "custom"
+	}
+	if _, ok := err.(*RetryExhaustionError); ok {
+		return "retry"
+	}
+
+	var msg string
+	if e, ok := err.(error); ok {
+		msg = e.Error()
+	} else if s, ok := err.(string); ok {
+		msg = s
+	} else {
+		msg = fmt.Sprint(err)
+	}
+
+	return ClassifyErrorMessage(msg)
+}
+
+func ClassifyErrorMessage(msg string) string {
+	lower := strings.ToLower(msg)
+
+	// Check retry
+	if strings.Contains(lower, "retry limit") || strings.Contains(lower, "retry exhaustion") {
+		return "retry"
+	}
+
+	// Check index out-of-range/bounds
+	if strings.Contains(lower, "index out of range") ||
+		strings.Contains(lower, "slice index out of range") ||
+		strings.Contains(lower, "out of range") ||
+		strings.Contains(lower, "out of bounds") {
+		return "index"
+	}
+
+	// Check type-conversion failures
+	if strings.Contains(lower, "invalid operation: int(") ||
+		strings.Contains(lower, "invalid operation: int64(") ||
+		strings.Contains(lower, "invalid operation: float(") ||
+		strings.Contains(lower, "invalid argument for int") ||
+		strings.Contains(lower, "invalid argument for float") ||
+		strings.Contains(lower, "cannot convert") ||
+		strings.Contains(lower, "conversion") ||
+		strings.Contains(lower, "parsing \"") {
+		return "conversion"
+	}
+
+	// Check nil-pointer / reference
+	if strings.Contains(lower, "nil pointer") ||
+		strings.Contains(lower, "nil dereference") ||
+		strings.Contains(lower, "invalid memory address or nil pointer dereference") ||
+		strings.Contains(lower, "cannot call nil") ||
+		strings.Contains(lower, "dereference of nil") ||
+		strings.Contains(lower, "nil reference") ||
+		strings.Contains(lower, "from <nil>") ||
+		strings.Contains(lower, "from nil") {
+		return "nil"
+	}
+
+	// Check type-mismatch / assertion
+	if strings.Contains(lower, "type mismatch") ||
+		strings.Contains(lower, "invalid operation:") ||
+		strings.Contains(lower, "cannot call non-function") ||
+		strings.Contains(lower, "cannot fetch") ||
+		strings.Contains(lower, "cannot use") ||
+		strings.Contains(lower, "is not comparable") ||
+		strings.Contains(lower, "type is not comparable") ||
+		strings.Contains(lower, "interface conversion") ||
+		strings.Contains(lower, "type assertion") ||
+		strings.Contains(lower, "invalid argument for") ||
+		strings.Contains(lower, "is not a") ||
+		strings.Contains(lower, "expected ") {
+		return "type"
+	}
+
+	return "custom"
+}
