+	}
+
+	if isIndexError(msg) {
+		return "index"
+	}
+
+	if isConversionError(msg) {
+		return "conversion"
+	}
+
+	if isNilError(msg) {
+		return "nil"
+	}
+
+	if isTypeError(msg) {
+		return "type"
+	}
+
+	return "custom"
