+func TestRetry(t *testing.T) {
+	t.Run("retry succeeds within limit", func(t *testing.T) {
+		attempts := 0
+		env := map[string]any{
+			"getAttempts": func() int { return attempts },
+			"incAttempts": func() int {
+				attempts++
+				return attempts
+			},
+		}
+
+		code := `
+			try {
+				incAttempts();
+				if getAttempts() < 3 {
+					throw("try again");
+				} else {
+					"success";
+				};
+			} catch {
+				retry;
+			}
+		`
+		out, err := expr.Eval(code, env)
+		require.NoError(t, err)
+		assert.Equal(t, "success", out)
+		assert.Equal(t, 3, attempts)
+	})
+
+	t.Run("retry limit exceeded raises distinct exhaustion error", func(t *testing.T) {
+		attempts := 0
+		env := map[string]any{
+			"inc": func() int {
+				attempts++
+				return attempts
+			},
+		}
+
+		code := `
+			try {
+				inc();
+				throw("fail always");
+			} catch {
+				retry;
+			}
+		`
+		_, err := expr.Eval(code, env)
+		require.Error(t, err)
+		assert.Contains(t, err.Error(), "retry limit exceeded")
+		// Initial attempt (1) + 3 retries = 4 attempts total
+		assert.Equal(t, 4, attempts)
+	})
+
+	t.Run("retry exhaustion classified as retry by errtype", func(t *testing.T) {
+		code := `
+			try {
+				try {
+					throw("fail");
+				} catch {
+					retry;
+				}
+			} catch e {
+				errtype(e);
+			}
+		`
+		out, err := expr.Eval(code, nil)
+		require.NoError(t, err)
+		assert.Equal(t, "retry", out)
+	})
+
+	t.Run("retry outside catch block raises runtime error", func(t *testing.T) {
+		_, err := expr.Eval(`retry`, nil)
+		require.Error(t, err)
+		assert.Contains(t, err.Error(), "retry outside catch block")
+
+		// Inside try body
+		out, err := expr.Eval(`try { retry } catch e { e.Message }`, nil)
+		require.NoError(t, err)
+		assert.Equal(t, "retry outside catch block", out)
+
+		// Inside finally
+		_, err = expr.Eval(`try { 1 } finally { retry }`, nil)
+		require.Error(t, err)
+		assert.Contains(t, err.Error(), "retry outside catch block")
+	})
+}
