+		if p.err != nil {
+			return nil
+		}
+		if p.current.Is(Operator, ",") {
+			p.error("try() requires exactly two arguments")
+			return nil
+		}
+		p.expect(Bracket, ")")
+		if p.err != nil {
+			return nil
+		}
+
+		catchNode := p.createNode(&CatchNode{
+			Body: fallback,
+		}, token.Location).(*CatchNode)
+
+		return p.createNode(&TryNode{
+			Try:      expr,
+			Catches:  []*CatchNode{catchNode},
+			CallForm: true,
+		}, token.Location)
