+					p.next() // consume 'is'
+					if p.current.Kind != String {
+						p.error("expected string literal after 'is'")
+						return nil
+					}
+					pattern = p.current.Value
+					p.next() // consume string
+				}
+			}
+
+			p.expect(Bracket, "{")
+			if p.err != nil {
+				return nil
+			}
+			var handler Node
+			if p.current.Is(Bracket, "}") {
+				handler = p.createNode(&NilNode{}, catchToken.Location)
+			} else {
+				handler = p.parseSequenceExpression()
+				if p.err != nil {
+					return nil
+				}
+			}
+			p.expect(Bracket, "}")
+			if p.err != nil {
+				return nil
+			}
+
+			catches = append(catches, p.createNode(&CatchNode{
+				Name:    catchVar,
+				Pattern: pattern,
+				Body:    handler,
+			}, catchToken.Location).(*CatchNode))
+		}
+
+		var finally Node
+		if p.current.Is(Identifier, "finally") {
+			finallyToken := p.current
+			p.next() // consume 'finally'
+			p.expect(Bracket, "{")
+			if p.err != nil {
+				return nil
+			}
+			if p.current.Is(Bracket, "}") {
+				finally = p.createNode(&NilNode{}, finallyToken.Location)
+			} else {
+				finally = p.parseSequenceExpression()
+				if p.err != nil {
+					return nil
+				}
+			}
+			p.expect(Bracket, "}")
+			if p.err != nil {
+				return nil
+			}
+		}
+
+		if len(catches) == 0 && finally == nil {
+			p.error("expected catch or finally after try")
+			return nil
+		}
+
+		return p.createNode(&TryNode{
+			Try:     tryBody,
+			Catches: catches,
+			Finally: finally,
+		}, token.Location)
+	}
+
+	p.error("expected ( or { after try")
+	return nil
+}
+
