+package runtime
+
+import (
+	"fmt"
+)
+
+type CustomError struct {
+	Value   any
+	Message string
+}
+
+func NewCustomError(val any) *CustomError {
+	if ce, ok := val.(*CustomError); ok {
+		return ce
+	}
+	return &CustomError{
+		Value:   val,
+		Message: fmt.Sprint(val),
+	}
+}
+
+func (e *CustomError) Error() string {
+	return e.Message
+}
+
+type RetryExhaustionError struct {
+	Message string
+}
+
+func (e *RetryExhaustionError) Error() string {
+	if e.Message != "" {
+		return e.Message
+	}
+	return "retry limit exceeded"
+}
+
+type RetrySignal struct{}
+
+func (s RetrySignal) Error() string {
+	return "retry outside catch block"
+}
+
+func IsRetrySignal(r any) bool {
+	_, ok := r.(RetrySignal)
+	return ok
+}
+
+func IsCustomError(err error) bool {
+	if err == nil {
+		return false
+	}
+	for err != nil {
+		if _, ok := err.(*CustomError); ok {
+			return true
+		}
+		if u, ok := err.(interface{ Unwrap() error }); ok {
+			err = u.Unwrap()
+		} else {
+			break
+		}
+	}
+	return false
+}
+
+func IsRetryExhaustion(err error, msg string) bool {
+	for e := err; e != nil; {
+		if _, ok := e.(*RetryExhaustionError); ok {
+			return true
+		}
+		if u, ok := e.(interface{ Unwrap() error }); ok {
+			e = u.Unwrap()
+		} else {
+			break
+		}
+	}
+	if msg == "retry limit exceeded" || msg == "retry exhaustion" {
+		return true
+	}
+	return false
+}
