@@ -0,0 +1,136 @@
+package builtin
+
+import (
+	"errors"
+	"strings"
+)
+
+// RuntimeError represents a runtime error in expr expressions.
+type RuntimeError struct {
+	Message string
+	Type    string
+	Value   any
+}
+
+func (e RuntimeError) Error() string {
+	return e.Message
+}
+
+func (e RuntimeError) String() string {
+	return e.Message
+}
+
+// ClassifyError classifies a caught error value into one of:
+// "index", "conversion", "type", "nil", "retry", "custom", or "none".
+func ClassifyError(val any) string {
+	if val == nil {
+		return "none"
+	}
+
+	if re, ok := val.(*RuntimeError); ok {
+		if re == nil {
+			return "none"
+		}
+		if re.Type != "" {
+			return re.Type
+		}
+		return ClassifyErrorMessage(re.Message)
+	}
+
+	if re, ok := val.(RuntimeError); ok {
+		if re.Type != "" {
+			return re.Type
+		}
+		return ClassifyErrorMessage(re.Message)
+	}
+
+	var re *RuntimeError
+	if err, ok := val.(error); ok {
+		if errors.As(err, &re) {
+			if re.Type != "" {
+				return re.Type
+			}
+			return ClassifyErrorMessage(re.Message)
+		}
+		return ClassifyErrorMessage(err.Error())
+	}
+
+	if s, ok := val.(string); ok {
+		return ClassifyErrorMessage(s)
+	}
+
+	return "custom"
+}
+
+// ClassifyErrorMessage classifies an error message string.
+func ClassifyErrorMessage(msg string) string {
+	if strings.Contains(msg, "retry limit") ||
+		strings.Contains(msg, "retry exhaustion") ||
+		strings.Contains(msg, "retry exhausted") {
+		return "retry"
+	}
+
+	if strings.Contains(msg, "nil pointer") ||
+		strings.Contains(msg, "nil dereference") ||
+		strings.Contains(msg, "nil-pointer") ||
+		strings.Contains(msg, "nil reference") ||
+		strings.Contains(msg, "invalid memory address or nil pointer dereference") ||
+		(strings.Contains(msg, "cannot fetch") && strings.Contains(msg, "from <nil>")) ||
+		(strings.Contains(msg, "cannot get") && strings.Contains(msg, "from <nil>")) ||
+		strings.Contains(msg, "zero Value") ||
+		strings.HasPrefix(msg, "cannot get ") {
+		return "nil"
+	}
+
+	if strings.Contains(msg, "out of range") ||
+		strings.Contains(msg, "out of bounds") ||
+		strings.Contains(msg, "slice index") ||
+		strings.Contains(msg, "bounds out of range") {
+		return "index"
+	}
+
+	if strings.Contains(msg, "cannot parse") ||
+		strings.Contains(msg, "parsing time") ||
+		strings.Contains(msg, "invalid syntax") ||
+		strings.Contains(msg, "invalid date") ||
+		strings.Contains(msg, "invalid duration") ||
+		strings.Contains(msg, "unknown unit") ||
+		strings.Contains(msg, "missing unit") ||
+		strings.Contains(msg, "unknown time zone") ||
+		strings.Contains(msg, "invalid location") ||
+		strings.Contains(msg, "illegal base64") ||
+		strings.Contains(msg, "cannot unmarshal") ||
+		strings.Contains(msg, "unexpected end of JSON") ||
+		strings.Contains(msg, "error parsing regexp") ||
+		strings.HasPrefix(msg, "invalid operation: int(") ||
+		strings.HasPrefix(msg, "invalid operation: int64(") ||
+		strings.HasPrefix(msg, "invalid operation: float(") ||
+		strings.HasPrefix(msg, "invalid operation: bool(") {
+		return "conversion"
+	}
+
+	if strings.Contains(msg, "interface conversion") ||
+		strings.Contains(msg, "type assertion") ||
+		strings.Contains(msg, "type mismatch") ||
+		strings.Contains(msg, "mismatched types") ||
+		strings.Contains(msg, "invalid operation") ||
+		strings.Contains(msg, "is not assignable to type") ||
+		strings.Contains(msg, "cannot use") ||
+		strings.Contains(msg, "using interface {} as type") ||
+		strings.Contains(msg, "invalid argument for len") ||
+		strings.Contains(msg, "invalid argument for abs") ||
+		strings.Contains(msg, "not defined on") ||
+		strings.Contains(msg, "cannot slice") ||
