+func (c *compiler) TryNode(node *ast.TryNode) {
+	tryHandler := &TryHandler{
+		FinallyIP: -1,
+	}
+	handlerConst := c.addConstant(tryHandler)
+	c.emit(OpTry, handlerConst)
+
+	tryHandler.TryIP = len(c.bytecode)
+	c.compile(node.Body)
+	c.emit(OpEndTry)
+
+	var jumpsToEnd []int
+	var jumpsToFinally []int
+
+	if node.Finally != nil {
+		jumpsToFinally = append(jumpsToFinally, c.emit(OpJump, placeholder))
+	} else {
+		jumpsToEnd = append(jumpsToEnd, c.emit(OpJump, placeholder))
+	}
+
+	for _, catch := range node.Catches {
+		catchIP := len(c.bytecode)
+		tryHandler.Catches = append(tryHandler.Catches, CatchClause{
+			Is:      catch.Is,
+			CatchIP: catchIP,
+		})
+
+		if catch.Var != "" {
+			index := c.addVariable(catch.Var)
+			c.emit(OpStore, index)
+			c.beginScope(catch.Var, index)
+			c.compile(catch.Body)
+			c.endScope()
+		} else {
+			c.emit(OpPop)
+			c.compile(catch.Body)
+		}
+
+		c.emit(OpEndTry)
+		if node.Finally != nil {
+			jumpsToFinally = append(jumpsToFinally, c.emit(OpJump, placeholder))
+		} else {
+			jumpsToEnd = append(jumpsToEnd, c.emit(OpJump, placeholder))
+		}
+	}
+
+	if node.Finally != nil {
+		tryHandler.FinallyIP = len(c.bytecode)
+		for _, j := range jumpsToFinally {
+			c.patchJump(j)
+		}
+		c.compile(node.Finally)
+		c.emit(OpPop) // discard finally body result
+		c.emit(OpEndFinally)
+	}
+
+	tryHandler.EndIP = len(c.bytecode)
+	for _, j := range jumpsToEnd {
+		c.patchJump(j)
+	}
+}
