+func TestTryFunction(t *testing.T) {
+	t.Run("success returns expression result", func(t *testing.T) {
+		out, err := expr.Eval(`try(1 + 2, 42)`, nil)
+		require.NoError(t, err)
+		assert.Equal(t, 3, out)
+	})
+
+	t.Run("error returns fallback", func(t *testing.T) {
+		out, err := expr.Eval(`try(1 % 0, 42)`, nil)
+		require.NoError(t, err)
+		assert.Equal(t, 42, out)
+	})
+
+	t.Run("fallback is lazily evaluated", func(t *testing.T) {
+		out, err := expr.Eval(`try("success", 1 % 0)`, nil)
+		require.NoError(t, err)
+		assert.Equal(t, "success", out)
+	})
+
+	t.Run("fallback with throw is lazily evaluated", func(t *testing.T) {
+		out, err := expr.Eval(`try("ok", throw("should not be thrown"))`, nil)
+		require.NoError(t, err)
+		assert.Equal(t, "ok", out)
+	})
+
+	t.Run("error in fallback propagates", func(t *testing.T) {
+		_, err := expr.Eval(`try([1][10], throw("fallback error"))`, nil)
+		require.Error(t, err)
+		assert.Contains(t, err.Error(), "fallback error")
+	})
+
+	t.Run("requires exactly two arguments", func(t *testing.T) {
+		_, err := expr.Compile(`try(1)`)
+		require.Error(t, err)
+
+		_, err = expr.Compile(`try(1, 2, 3)`)
+		require.Error(t, err)
+	})
+}
+
+func TestTryCatchBlock(t *testing.T) {
