+	})
+
+	t.Run("finally executes after caught error and preserves catch result", func(t *testing.T) {
+		env := &cleanupEnv{}
+		program, err := expr.Compile(`try { throw("error") } catch { 200 } finally { Cleanup() }`, expr.Env(env))
+		require.NoError(t, err)
+		out, err := expr.Run(program, env)
+		require.NoError(t, err)
+		assert.Equal(t, 200, out)
+		assert.True(t, env.Cleaned)
+	})
+
+	t.Run("finally executes after uncaught error and error propagates", func(t *testing.T) {
+		env := &cleanupEnv{}
+		program, err := expr.Compile(`try { throw("uncaught") } finally { Cleanup() }`, expr.Env(env))
+		require.NoError(t, err)
