+type FlakyService struct {
+	Calls int
+}
+
+func (s *FlakyService) FlakySuccess() string {
+	s.Calls++
+	if s.Calls < 3 {
+		panic("temporary network failure")
+	}
+	return "ok"
+}
+
+func (s *FlakyService) AlwaysFail() string {
+	s.Calls++
+	panic("persistent failure")
+}
