+func TestRetry(t *testing.T) {
+	t.Run("retry succeeds after failures within limit", func(t *testing.T) {
+		svc := &FlakyService{}
+		program, err := expr.Compile(`try { FlakySuccess() } catch { retry }`, expr.Env(svc))
+		require.NoError(t, err)
+		out, err := expr.Run(program, svc)
+		require.NoError(t, err)
+		assert.Equal(t, "ok", out)
+		assert.Equal(t, 3, svc.Calls) // failed on call 1 and 2, succeeded on call 3
+	})
+
+	t.Run("retry limit exceeded raises distinct exhaustion error", func(t *testing.T) {
+		svc := &FlakyService{}
