+	t.Run("outer catch classifies retry exhaustion", func(t *testing.T) {
+		src := `
+			try {
+				try {
+					1 % 0
+				} catch {
+					retry
+				}
+			} catch e {
+				errtype(e)
+			}
+		`
+		out, err := expr.Eval(src, nil)
+		require.NoError(t, err)
+		assert.Equal(t, "retry", out)
+	})
+
+	t.Run("retry outside catch block raises runtime error", func(t *testing.T) {
+		_, err := expr.Eval(`retry`, nil)
+		require.Error(t, err)
+		assert.Contains(t, err.Error(), "retry used outside of catch block")
