+++ b/test/multicolumn-spec.ts
@@ -0,0 +1,91 @@
+import katex from "../katex";
+
+const render = (tex: string) => katex.renderToString(tex, {throwOnError: true});
+const renderMathML = (tex: string) => katex.renderToString(tex, {throwOnError: true, output: "mathml"});
+const renderHTML = (tex: string) => katex.renderToString(tex, {throwOnError: true, output: "html"});
+
+const mustThrow = (tex: string, why: string) => {
+    let threw = false;
+    try {
+        render(tex);
+    } catch (e) {
+        threw = true;
+    }
+    if (!threw) {
+        throw new Error("expected ParseError: " + why + " [" + tex + "]");
+    }
+};
+
+describe("multicolumn", () => {
+    it("renders in all supported environments", () => {
+        const envs = [
+            "array",
+            "matrix",
+            "pmatrix",
+            "bmatrix",
+            "Bmatrix",
+            "vmatrix",
+            "Vmatrix",
+            "cases",
+            "rcases",
+            "aligned",
+            "smallmatrix",
+        ];
+        for (const env of envs) {
+            if (env === "array") {
+                const out = render(`\\begin{array}{cc}\\multicolumn{2}{c}{x}\\end{array}`);
+                expect(out).toContain("columnspan");
+            } else {
+                const out = render(`\\begin{${env}}\\multicolumn{1}{c}{x}\\end{${env}}`);
+                expect(out).toContain("columnspan");
+            }
+        }
+    });
+
+    it("emits MathML columnspan and columnalign", () => {
+        const mml = renderMathML("\\begin{array}{ccc}\\multicolumn{2}{r}{x}&y\\end{array}");
+        expect(mml).toContain('columnspan="2"');
+        expect(mml).toContain('columnalign="right"');
+    });
+
+    it("overrides column alignment in HTML", () => {
+        const html = renderHTML("\\begin{array}{l}\\multicolumn{1}{r}{x}\\end{array}");
+        expect(html).toContain("col-align-r");
+    });
+
+    it("suppresses internal vertical separators in HTML", () => {
+        const withSep = renderHTML(
+            "\\begin{array}{|c|c|} a & b \\\\ \\multicolumn{2}{|c|}{c} \\end{array}"
+        );
+        expect(withSep).toBeDefined();
+    });
+
+    it("supports multiple multicolumns in the same row", () => {
+        const html = render(
+            "\\begin{array}{cccc}\\multicolumn{2}{c}{A}&\\multicolumn{2}{r}{B}\\end{array}"
+        );
+        expect(html).toContain('columnspan="2"');
+    });
+
+    it("throws ParseError for invalid n", () => {
+        mustThrow("\\begin{array}{cc}\\multicolumn{0}{c}{x}\\end{array}", "n < 1");
+        mustThrow("\\begin{array}{cc}\\multicolumn{-1}{c}{x}\\end{array}", "n negative");
+        mustThrow("\\begin{array}{cc}\\multicolumn{1.5}{c}{x}\\end{array}", "non-integer n");
+        mustThrow("\\begin{array}{cc}\\multicolumn{foo}{c}{x}\\end{array}", "string n");
+        mustThrow("\\begin{array}{cc}\\multicolumn{3}{c}{x}\\end{array}", "n exceeds total columns");
+        mustThrow("\\begin{array}{cc}a & \\multicolumn{2}{c}{x}\\end{array}", "n exceeds remaining columns");
+    });
+
+    it("throws ParseError for invalid alignment", () => {
+        mustThrow("\\begin{array}{cc}\\multicolumn{1}{q}{x}\\end{array}", "invalid alignment char");
+        mustThrow("\\begin{array}{cc}\\multicolumn{1}{cc}{x}\\end{array}", "multiple alignment chars");
+        mustThrow("\\begin{array}{cc}\\multicolumn{1}{lr}{x}\\end{array}", "multiple alignment chars");
+        mustThrow("\\begin{array}{cc}\\multicolumn{1}{|}{x}\\end{array}", "no alignment char");
+        mustThrow("\\begin{array}{cc}\\multicolumn{1}{}{x}\\end{array}", "empty alignment");
+    });
+
+    it("throws ParseError when used outside array-like environments", () => {
+        mustThrow("\\multicolumn{1}{c}{x}", "top-level");
+        mustThrow("\\text{\\multicolumn{1}{c}{x}}", "inside text");
+    });
+});

