--- /dev/null
+++ b/src/functions/multicolumn.ts
@@ -0,0 +1,121 @@
+import defineFunction from "../defineFunction";
+import {assertNodeType} from "../parseNode";
+import ParseError from "../ParseError";
+import {makeSpan} from "../buildCommon";
+import * as html from "../buildHTML";
+import * as mml from "../buildMathML";
+import type {AnyParseNode, ParseNode} from "../parseNode";
+
+export const SUPPORTED_ENVIRONMENTS = new Set([
+    "array",
+    "matrix",
+    "pmatrix",
+    "bmatrix",
+    "Bmatrix",
+    "vmatrix",
+    "Vmatrix",
+    "cases",
+    "rcases",
+    "aligned",
+    "smallmatrix",
+]);
+
+export function getMulticolumn(cell: AnyParseNode | null | undefined): ParseNode<"multicolumn"> | null {
+    if (!cell) {
+        return null;
+    }
+    if (cell.type === "multicolumn") {
+        return cell;
+    }
+    if (cell.type === "styling" && cell.body.length > 0) {
+        return getMulticolumn(cell.body[0]);
+    }
+    if (cell.type === "ordgroup" && cell.body.length > 0) {
+        return getMulticolumn(cell.body[0]);
+    }
+    return null;
+}
+
+defineFunction({
+    type: "multicolumn",
+    names: ["\\multicolumn"],
+    props: {
+        numArgs: 3,
+        argTypes: ["raw", "raw", "original"],
+        allowedInText: true,
+        allowedInMath: true,
+    },
+    handler(context, args) {
+        const {parser} = context;
+        const currentEnv = parser.currentEnv();
+
+        if (!currentEnv || !SUPPORTED_ENVIRONMENTS.has(currentEnv) || !parser.activeArray) {
+            throw new ParseError(
+                "\\multicolumn can only be used inside array-like environments",
+                context.token,
+            );
+        }
+
+        if (parser.activeArray.cellTokensCount > 0 || parser.activeArray.cellDepth > 1) {
+            throw new ParseError(
+                "\\multicolumn must be the first item in a cell",
+                context.token,
+            );
+        }
+
+        // Validate n: must be an integer >= 1
+        const nNode = assertNodeType(args[0], "raw");
+        const nStr = nNode.string.trim();
+        if (!/^-?\d+$/.test(nStr)) {
+            throw new ParseError("Invalid column count in \\multicolumn: " + nStr, context.token);
+        }
+        const n = parseInt(nStr, 10);
+        if (n < 1) {
+            throw new ParseError("Column count in \\multicolumn must be at least 1: " + nStr, context.token);
+        }
+
+        // Check if n exceeds remaining columns in the current row
+        const {totalCols, currentCol} = parser.activeArray;
+        if (totalCols != null) {
+            const remaining = totalCols - currentCol;
+            if (n > remaining) {
+                throw new ParseError(
+                    `\\multicolumn count ${n} exceeds remaining columns (${remaining}) in current row`,
+                    context.token,
+                );
+            }
+        }
+
+        // Validate alignment: exactly one of l, c, or r with optional | for vertical rules
+        const alignNode = assertNodeType(args[1], "raw");
+        const alignStr = alignNode.string.replace(/\s+/g, "");
+        const match = /^(\|*)([lcr])(\|*)$/.exec(alignStr);
+        if (!match) {
+            throw new ParseError("Invalid alignment in \\multicolumn: " + alignNode.string, context.token);
+        }
+
+        const beforeRules = match[1].length;
+        const align = match[2] as "l" | "c" | "r";
+        const afterRules = match[3].length;
+
+        const content = args[2];
+        const body = content.type === "ordgroup" ? content.body : [content];
+
+        return {
+            type: "multicolumn",
+            mode: parser.mode,
+            loc: context.token?.loc,
+            n,
+            align,
+            beforeRules,
+            afterRules,
+            body,
+        };
+    },
+    htmlBuilder(group, options) {
+        return makeSpan(["mord"], html.buildExpression(group.body, options, true), options);
+    },
+    mathmlBuilder(group, options) {
+        return mml.buildExpressionRow(group.body, options, true);
+    },
+});
