+import * as t from 'node:assert/strict';
+import { describe, it } from 'vitest';
+import { parseScript, parseModule } from '../../../src/meriyah';
+
+describe('Declarations - using and await using', () => {
+  it('parses using declaration in module', () => {
+    const ast = parseModule('using x = null;', { next: true });
+    t.equal(ast.body[0].type, 'VariableDeclaration');
+    const decl = ast.body[0] as any;
+    t.equal(decl.kind, 'using');
+    t.equal(decl.declarations.length, 1);
+    t.equal(decl.declarations[0].id.name, 'x');
+    t.equal(decl.declarations[0].init.type, 'Literal');
+  });
+
+  it('parses multiple declarators in using declaration', () => {
+    const ast = parseModule('using x = 1, y = 2;', { next: true });
+    const decl = ast.body[0] as any;
+    t.equal(decl.kind, 'using');
+    t.equal(decl.declarations.length, 2);
+  });
+
+  it('parses using as identifier name in using declaration', () => {
+    const ast = parseModule('using using = null;', { next: true });
+    const decl = ast.body[0] as any;
+    t.equal(decl.kind, 'using');
+    t.equal(decl.declarations[0].id.name, 'using');
+  });
+
+  it('parses await using declaration in module', () => {
+    const ast = parseModule('await using y = null;', { next: true });
+    const decl = ast.body[0] as any;
+    t.equal(decl.type, 'VariableDeclaration');
+    t.equal(decl.kind, 'await using');
+  });
+
+  it('parses await using declaration in async function', () => {
+    const ast = parseScript('async function f() { await using y = null; }', { next: true });
+    const fn = ast.body[0] as any;
+    const decl = fn.body.body[0];
+    t.equal(decl.type, 'VariableDeclaration');
+    t.equal(decl.kind, 'await using');
+  });
+
+  it('parses using in script block or function', () => {
+    const ast1 = parseScript('{ using x = null; }', { next: true });
+    const block = ast1.body[0] as any;
+    t.equal(block.body[0].kind, 'using');
+
+    const ast2 = parseScript('function f() { using x = null; }', { next: true });
+    const fn = ast2.body[0] as any;
+    t.equal(fn.body.body[0].kind, 'using');
+  });
+
+  it('treats using as identifier when followed by newline', () => {
+    const ast = parseModule('using\nx = null;', { next: true });
+    t.equal(ast.body[0].type, 'ExpressionStatement');
+    t.notEqual((ast.body[0] as any).kind, 'using');
+  });
+
+  it('parses for-of with using in head', () => {
+    const ast = parseScript('for (using x of list) {}', { next: true });
+    const loop = ast.body[0] as any;
+    t.equal(loop.type, 'ForOfStatement');
+    t.equal(loop.left.type, 'VariableDeclaration');
+    t.equal(loop.left.kind, 'using');
+    t.equal(loop.left.declarations[0].init, null);
+    t.equal(loop.await, false);
+  });
+
+  it('parses for-await-of with using in head', () => {
+    const ast = parseModule('for await (using x of list) {}', { next: true });
+    const loop = ast.body[0] as any;
+    t.equal(loop.type, 'ForOfStatement');
+    t.equal(loop.left.kind, 'using');
+    t.equal(loop.await, true);
+  });
+
+  it('parses for-of with await using in head', () => {
+    const ast = parseModule('for (await using x of list) {}', { next: true });
+    const loop = ast.body[0] as any;
+    t.equal(loop.type, 'ForOfStatement');
+    t.equal(loop.left.kind, 'await using');
+    t.equal(loop.await, false);
+  });
+
+  it('parses for-await-of with await using in head', () => {
+    const ast = parseModule('for await (await using x of list) {}', { next: true });
+    const loop = ast.body[0] as any;
+    t.equal(loop.type, 'ForOfStatement');
+    t.equal(loop.left.kind, 'await using');
+    t.equal(loop.await, true);
+  });
+
+  it('throws expected errors for invalid using usage', () => {
+    const mustThrow = (src: string, needle: string, parse?: any) => {
+      let msg: string | null = null;
+      try {
+        (parse || parseModule)(src, { next: true });
+      } catch (e: any) {
+        msg = e.message;
