diff --git a/processor/bounded_memory.go b/processor/bounded_memory.go
new file mode 100644
index 0000000..884e62c
--- /dev/null
+++ b/processor/bounded_memory.go
@@ -0,0 +1,473 @@
+package processor
+
+import (
+	"bufio"
+	"bytes"
+	"cmp"
+	"fmt"
+	"io"
+	"math"
+	"os"
+	"path/filepath"
+	"slices"
+	"strings"
+	"sync"
+
+	jsoniter "github.com/json-iterator/go"
+)
+
+type boundedMemoryState struct {
+	maxInMemory       int
+	spillDir          string
+	spills            int
+	peakInMemoryFiles int
+	currentBatch      []*FileJob
+	spillFiles        []string
+	sortedSpillFile   string
+}
+
+func fileSummarizeMultiBounded(input chan *FileJob) string {
+	state := &boundedMemoryState{
+		maxInMemory:  BoundedMemoryMaxInMemoryFiles,
+		spillDir:     BoundedMemoryDir,
+		currentBatch: make([]*FileJob, 0, BoundedMemoryMaxInMemoryFiles),
+	}
+
+	for res := range input {
+		if len(state.currentBatch) >= state.maxInMemory {
+			state.spills++
+			spillPath := filepath.Join(state.spillDir, fmt.Sprintf("spill_%d.jsonl", state.spills))
+			if err := state.writeSpillBatch(spillPath, state.currentBatch); err != nil {
+				fmt.Fprintf(os.Stderr, "error writing spill file %s: %s\n", spillPath, err)
+			}
+			state.spillFiles = append(state.spillFiles, spillPath)
+			state.currentBatch = state.currentBatch[:0]
+		}
+		state.currentBatch = append(state.currentBatch, res)
+		if len(state.currentBatch) > state.peakInMemoryFiles {
+			state.peakInMemoryFiles = len(state.currentBatch)
+		}
+	}
+
+	if state.spills > 0 && len(state.currentBatch) > 0 {
+		state.spills++
+		spillPath := filepath.Join(state.spillDir, fmt.Sprintf("spill_%d.jsonl", state.spills))
+		if err := state.writeSpillBatch(spillPath, state.currentBatch); err != nil {
+			fmt.Fprintf(os.Stderr, "error writing spill file %s: %s\n", spillPath, err)
+		}
+		state.spillFiles = append(state.spillFiles, spillPath)
+		state.currentBatch = state.currentBatch[:0]
+	}
+
+	// If sorting requested and we have spilled files, create merged sorted file
+	if SortBy != "" && len(state.spillFiles) > 0 {
+		if len(state.spillFiles) == 1 {
+			state.sortedSpillFile = state.spillFiles[0]
+		} else {
+			merged, err := state.mergeSpillFiles(state.spillFiles)
+			if err != nil {
+				fmt.Fprintf(os.Stderr, "error merging spill files: %s\n", err)
+			} else {
+				state.sortedSpillFile = merged
+			}
+		}
+	}
+
+	var str strings.Builder
+
+	for s := range strings.SplitSeq(FormatMulti, ",") {
+		t := strings.Split(s, ":")
+		if len(t) != 2 {
+			continue
+		}
+		formatType := strings.ToLower(t[0])
+		dest := t[1]
+
+		if formatType == "csv-stream" {
+			files := state.spillFiles
+			if SortBy != "" && state.sortedSpillFile != "" {
+				files = []string{state.sortedSpillFile}
+			}
+			if err := state.handleCSVStream(dest, files, &str); err != nil {
+				fmt.Fprintf(os.Stderr, "error writing csv-stream to %s: %s\n", dest, err)
+			}
+			continue
+		}
+
+		files := state.spillFiles
+		if Files && SortBy != "" && state.sortedSpillFile != "" {
+			files = []string{state.sortedSpillFile}
+		}
+
+		val := ""
+		switch formatType {
+		case "tabular":
+			val = state.streamJobs(files, fileSummarizeShort)
+		case "wide":
+			val = state.streamJobs(files, fileSummarizeLong)
+		case "json":
+			val = state.streamJobs(files, toJSON)
+		case "json2":
+			val = state.streamJobs(files, toJSON2)
+		case "cloc-yaml", "cloc-yml":
+			val = state.streamJobs(files, toClocYAML)
+		case "csv":
+			val = state.streamJobs(files, toCSV)
+		case "html":
+			val = state.streamJobs(files, toHtml)
+		case "html-table":
+			val = state.streamJobs(files, toHtmlTable)
+		case "sql":
+			val = state.streamJobs(files, toSql)
+		case "sql-insert":
+			val = state.streamJobs(files, toSqlInsert)
+		case "openmetrics":
+			val = state.streamJobs(files, toOpenMetrics)
+		}
+
+		if dest == "stdout" {
+			str.WriteString(val)
+			str.WriteString("\n")
+		} else {
+			err := os.WriteFile(dest, []byte(val), 0600)
+			if err != nil {
+				fmt.Printf("%s unable to be written to for format %s: %s\n", dest, formatType, err)
+			}
+		}
+	}
+
+	if BoundedMemoryStats {
+		fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", state.spills, state.peakInMemoryFiles)
+	}
+
+	return str.String()
+}
+
+func (b *boundedMemoryState) writeSpillBatch(path string, batch []*FileJob) error {
+	f, err := os.OpenFile(path, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0644)
+	if err != nil {
+		return err
+	}
+	defer f.Close()
+
+	if SortBy != "" {
+		slices.SortFunc(batch, func(x, y *FileJob) int {
+			return compareFileJobs(x, y, SortBy)
+		})
+	}
+
+	w := bufio.NewWriter(f)
+	for _, job := range batch {
+		data, err := jsoniter.ConfigCompatibleWithStandardLibrary.Marshal(job)
+		if err != nil {
+			return err
+		}
+		if SortBy != "" {
+			key := getSortKey(job, SortBy)
+			_, _ = w.WriteString(key)
+			_ = w.WriteByte('\t')
+		}
+		_, _ = w.Write(data)
+		_ = w.WriteByte('\n')
+	}
+	return w.Flush()
+}
+
+func getSortKey(job *FileJob, sortBy string) string {
+	switch strings.ToLower(sortBy) {
+	case "line", "lines":
+		return fmt.Sprintf("%019d\t%s", math.MaxInt64-job.Lines, job.Filename)
+	case "blank", "blanks":
+		return fmt.Sprintf("%019d\t%s", math.MaxInt64-job.Blank, job.Filename)
+	case "code", "codes":
+		return fmt.Sprintf("%019d\t%s", math.MaxInt64-job.Code, job.Filename)
+	case "comment", "comments":
+		return fmt.Sprintf("%019d\t%s", math.MaxInt64-job.Comment, job.Filename)
+	case "complexity", "complexitys":
+		return fmt.Sprintf("%019d\t%s", math.MaxInt64-job.Complexity, job.Filename)
+	case "byte", "bytes":
+		return fmt.Sprintf("%019d\t%s", math.MaxInt64-job.Bytes, job.Filename)
+	case "language", "languages", "lang", "langs":
+		return fmt.Sprintf("%s\t%s", job.Language, job.Filename)
+	default:
+		return fmt.Sprintf("%s\t%s", job.Filename, job.Filename)
+	}
+}
+
+func compareFileJobs(a, b *FileJob, sortBy string) int {
+	switch strings.ToLower(sortBy) {
+	case "name", "names":
+		return strings.Compare(a.Filename, b.Filename)
+	case "language", "languages", "lang", "langs":
+		if c := strings.Compare(a.Language, b.Language); c != 0 {
+			return c
+		}
+		return strings.Compare(a.Filename, b.Filename)
+	case "line", "lines":
+		if c := cmp.Compare(b.Lines, a.Lines); c != 0 {
+			return c
+		}
+		return strings.Compare(a.Filename, b.Filename)
+	case "blank", "blanks":
+		if c := cmp.Compare(b.Blank, a.Blank); c != 0 {
+			return c
+		}
+		return strings.Compare(a.Filename, b.Filename)
+	case "code", "codes":
+		if c := cmp.Compare(b.Code, a.Code); c != 0 {
+			return c
+		}
+		return strings.Compare(a.Filename, b.Filename)
+	case "comment", "comments":
+		if c := cmp.Compare(b.Comment, a.Comment); c != 0 {
+			return c
+		}
+		return strings.Compare(a.Filename, b.Filename)
+	case "complexity", "complexitys":
+		if c := cmp.Compare(b.Complexity, a.Complexity); c != 0 {
+			return c
+		}
+		return strings.Compare(a.Filename, b.Filename)
+	case "byte", "bytes":
+		if c := cmp.Compare(b.Bytes, a.Bytes); c != 0 {
+			return c
+		}
+		return strings.Compare(a.Filename, b.Filename)
+	default:
+		return strings.Compare(a.Filename, b.Filename)
+	}
+}
+
+func (b *boundedMemoryState) mergeSpillFiles(spillFiles []string) (string, error) {
+	current := spillFiles
+	mergeIndex := 0
+	for len(current) > 1 {
+		var next []string
+		for i := 0; i < len(current); i += 2 {
+			if i+1 < len(current) {
+				mergeIndex++
+				mergedPath := filepath.Join(b.spillDir, fmt.Sprintf("merged_%d.jsonl", mergeIndex))
+				if err := mergeTwoSpillFiles(current[i], current[i+1], mergedPath); err != nil {
+					return "", err
+				}
+				next = append(next, mergedPath)
+			} else {
+				next = append(next, current[i])
+			}
+		}
+		current = next
+	}
+	return current[0], nil
+}
+
+func mergeTwoSpillFiles(pathA, pathB, outPath string) error {
+	fA, err := os.Open(pathA)
+	if err != nil {
+		return err
+	}
+	defer fA.Close()
+
+	fB, err := os.Open(pathB)
+	if err != nil {
+		return err
+	}
+	defer fB.Close()
+
+	fOut, err := os.OpenFile(outPath, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0644)
+	if err != nil {
+		return err
+	}
+	defer fOut.Close()
+
+	w := bufio.NewWriter(fOut)
+	defer w.Flush()
+
+	scA := bufio.NewScanner(fA)
+	scB := bufio.NewScanner(fB)
+	scA.Buffer(make([]byte, 64*1024), 10*1024*1024)
+	scB.Buffer(make([]byte, 64*1024), 10*1024*1024)
+
+	hasA := scA.Scan()
+	hasB := scB.Scan()
+
+	for hasA && hasB {
+		lineA := scA.Bytes()
+		lineB := scB.Bytes()
+
+		keyA := extractSortKey(lineA)
+		keyB := extractSortKey(lineB)
+
+		if strings.Compare(keyA, keyB) <= 0 {
+			_, _ = w.Write(lineA)
+			_ = w.WriteByte('\n')
+			hasA = scA.Scan()
+		} else {
+			_, _ = w.Write(lineB)
+			_ = w.WriteByte('\n')
+			hasB = scB.Scan()
+		}
+	}
+
+	for hasA {
+		_, _ = w.Write(scA.Bytes())
+		_ = w.WriteByte('\n')
+		hasA = scA.Scan()
+	}
+
+	for hasB {
+		_, _ = w.Write(scB.Bytes())
+		_ = w.WriteByte('\n')
+		hasB = scB.Scan()
+	}
+
+	return nil
+}
+
+func extractSortKey(line []byte) string {
+	idx := bytes.IndexByte(line, '{')
+	if idx > 0 {
+		return string(line[:idx-1])
+	}
+	return ""
+}
+
+func (b *boundedMemoryState) streamJobs(files []string, fn func(chan *FileJob) string) string {
+	ch := make(chan *FileJob)
+	var res string
+	var wg sync.WaitGroup
+	wg.Add(1)
+
+	go func() {
+		defer wg.Done()
+		res = fn(ch)
+	}()
+
+	if b.spills == 0 {
+		for _, job := range b.currentBatch {
+			ch <- job
+		}
+	} else {
+		for _, spillFile := range files {
+			f, err := os.Open(spillFile)
+			if err != nil {
+				continue
+			}
+			scanner := bufio.NewScanner(f)
+			scanner.Buffer(make([]byte, 64*1024), 10*1024*1024)
+			for scanner.Scan() {
+				line := scanner.Bytes()
+				if len(line) == 0 {
+					continue
+				}
+				idx := bytes.IndexByte(line, '{')
+				if idx >= 0 {
+					line = line[idx:]
+				}
+				var job FileJob
+				if err := jsoniter.ConfigCompatibleWithStandardLibrary.Unmarshal(line, &job); err == nil {
+					ch <- &job
+				}
+			}
+			_ = f.Close()
+		}
+	}
+	close(ch)
+	wg.Wait()
+	return res
+}
+
+func (b *boundedMemoryState) handleCSVStream(dest string, files []string, str *strings.Builder) error {
+	var out io.Writer
+	var closeFile func()
+
+	if dest == "stdout" {
+		out = str
+		closeFile = func() {}
+	} else {
+		f, err := os.OpenFile(dest, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600)
+		if err != nil {
+			return err
+		}
+		bw := bufio.NewWriter(f)
+		out = bw
+		closeFile = func() {
+			_ = bw.Flush()
+			_ = f.Close()
+		}
+	}
+	defer closeFile()
+
+	header := "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n"
+	if _, err := io.WriteString(out, header); err != nil {
+		return err
+	}
+
+	writeRow := func(job *FileJob) {
+		loc := `"` + strings.ReplaceAll(job.Location, `"`, `""`) + `"`
+		fn := `"` + strings.ReplaceAll(job.Filename, `"`, `""`) + `"`
+		row := fmt.Sprintf("%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
+			job.Language, loc, fn, job.Lines, job.Code, job.Comment,
+			job.Blank, job.Complexity, job.Bytes, job.Uloc)
+		_, _ = io.WriteString(out, row)
+	}
+
+	if b.spills == 0 {
+		jobs := b.currentBatch
+		if SortBy != "" {
+			jobs = append([]*FileJob(nil), b.currentBatch...)
+			slices.SortFunc(jobs, func(a, b *FileJob) int {
+				return compareFileJobs(a, b, SortBy)
+			})
+		}
+		for _, job := range jobs {
+			writeRow(job)
+		}
+	} else {
+		for _, file := range files {
+			f, err := os.Open(file)
+			if err != nil {
+				continue
+			}
+			scanner := bufio.NewScanner(f)
+			scanner.Buffer(make([]byte, 64*1024), 10*1024*1024)
+			for scanner.Scan() {
+				line := scanner.Bytes()
+				if len(line) == 0 {
+					continue
+				}
+				idx := bytes.IndexByte(line, '{')
+				if idx >= 0 {
+					line = line[idx:]
+				}
+				var job FileJob
+				if err := jsoniter.ConfigCompatibleWithStandardLibrary.Unmarshal(line, &job); err == nil {
+					writeRow(&job)
+				}
+			}
+			_ = f.Close()
+		}
+	}
+	return nil
+}
+
+func isInsideDir(path, parentDir string) bool {
+	absParent, err := filepath.Abs(parentDir)
+	if err != nil {
+		return false
+	}
+	absPath, err := filepath.Abs(path)
+	if err != nil {
+		return false
+	}
+	if evalParent, err := filepath.EvalSymlinks(absParent); err == nil {
+		absParent = evalParent
+	}
+	if evalPath, err := filepath.EvalSymlinks(absPath); err == nil {
+		absPath = evalPath
+	}
+	rel, err := filepath.Rel(absParent, absPath)
+	if err != nil {
+		return false
+	}
+	return rel == "." || (!strings.HasPrefix(rel, "..") && !strings.HasPrefix(rel, string(filepath.Separator)))
+}
