+package processor
+
+import (
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+)
+
+func TestIsInsideDir(t *testing.T) {
+	tmpDir := t.TempDir()
+	child := filepath.Join(tmpDir, "child")
+	subChild := filepath.Join(child, "sub")
+	other := filepath.Join(t.TempDir(), "other")
+
+	if !isInsideDir(tmpDir, tmpDir) {
+		t.Errorf("expected tmpDir to be inside itself")
+	}
+	if !isInsideDir(child, tmpDir) {
+		t.Errorf("expected child to be inside tmpDir")
+	}
+	if !isInsideDir(subChild, tmpDir) {
+		t.Errorf("expected subChild to be inside tmpDir")
+	}
+	if isInsideDir(other, tmpDir) {
+		t.Errorf("expected other to NOT be inside tmpDir")
+	}
+}
+
+func TestBoundedMemorySpillAndMerge(t *testing.T) {
+	spillDir := t.TempDir()
+	state := &boundedMemoryState{
+		maxInMemory: 2,
+		spillDir:    spillDir,
+	}
+
+	jobs := []*FileJob{
+		{Filename: "b.go", Language: "Go", Lines: 20},
+		{Filename: "a.go", Language: "Go", Lines: 10},
+		{Filename: "c.go", Language: "Go", Lines: 30},
+	}
+
+	SortBy = "name"
+	defer func() { SortBy = "" }()
+
+	p1 := filepath.Join(spillDir, "spill_1.jsonl")
+	if err := state.writeSpillBatch(p1, jobs[:2]); err != nil {
+		t.Fatalf("failed to write batch 1: %v", err)
+	}
+
+	p2 := filepath.Join(spillDir, "spill_2.jsonl")
+	if err := state.writeSpillBatch(p2, jobs[2:]); err != nil {
+		t.Fatalf("failed to write batch 2: %v", err)
+	}
+
+	merged, err := state.mergeSpillFiles([]string{p1, p2})
+	if err != nil {
+		t.Fatalf("failed to merge: %v", err)
+	}
+
+	content, err := os.ReadFile(merged)
+	if err != nil {
+		t.Fatalf("failed to read merged: %v", err)
+	}
+
+	lines := strings.Split(strings.TrimSpace(string(content)), "\n")
+	if len(lines) != 3 {
+		t.Fatalf("expected 3 lines, got %d", len(lines))
+	}
+
+	// Verify lines are sorted by name: a.go, b.go, c.go
+	if !strings.Contains(lines[0], "a.go") {
+		t.Errorf("expected first line to be a.go, got: %s", lines[0])
+	}
+	if !strings.Contains(lines[1], "b.go") {
+		t.Errorf("expected second line to be b.go, got: %s", lines[1])
+	}
+	if !strings.Contains(lines[2], "c.go") {
+		t.Errorf("expected third line to be c.go, got: %s", lines[2])
+	}
+}
