+)
+
+func runSCCWithStderr(args ...string) (stdout string, stderr string, err error) {
+	args = slices.Insert(args, 0, sccTestFlag)
+	cmd := exec.Command(sccBinPath, args...)
+	var stdoutBuf, stderrBuf strings.Builder
+	cmd.Stdout = &stdoutBuf
+	cmd.Stderr = &stderrBuf
+	err = cmd.Run()
+	return stdoutBuf.String(), stderrBuf.String(), err
+}
+
+func TestBoundedMemoryFlagValidation(t *testing.T) {
+	tmpDir := t.TempDir()
+
+	// Missing bounded-memory-dir
+	_, _, err := runSCCWithStderr("--bounded-memory", tmpDir)
+	if err == nil {
+		t.Fatal("expected error when --bounded-memory-dir is missing")
+	}
+
+	// Invalid bounded-memory-max-in-memory-files (<= 0)
+	_, _, err = runSCCWithStderr("--bounded-memory", "--bounded-memory-dir", tmpDir, "--bounded-memory-max-in-memory-files", "0", tmpDir)
+	if err == nil {
+		t.Fatal("expected error when --bounded-memory-max-in-memory-files is 0")
+	}
+
+	_, _, err = runSCCWithStderr("--bounded-memory", "--bounded-memory-dir", tmpDir, "--bounded-memory-max-in-memory-files", "-5", tmpDir)
+	if err == nil {
+		t.Fatal("expected error when --bounded-memory-max-in-memory-files is negative")
+	}
+}
+
+func TestBoundedMemoryStatsOutput(t *testing.T) {
+	tmpDir := t.TempDir()
+	spillDir := filepath.Join(tmpDir, "spill")
+
+	// Create test files
+	file1 := filepath.Join(tmpDir, "test1.go")
+	file2 := filepath.Join(tmpDir, "test2.go")
+	file3 := filepath.Join(tmpDir, "test3.go")
+	_ = os.WriteFile(file1, []byte("package main\n\nfunc main() {}\n"), 0644)
+	_ = os.WriteFile(file2, []byte("package main\n\nfunc foo() {}\n"), 0644)
+	_ = os.WriteFile(file3, []byte("package main\n\nfunc bar() {}\n"), 0644)
+
+	// Test with stats and bounded-memory enabled with max=1 -> should have spills=2, peak=1
+	_, stderr, err := runSCCWithStderr(
+		"--bounded-memory",
+		"--bounded-memory-dir", spillDir,
+		"--bounded-memory-max-in-memory-files", "1",
+		"--bounded-memory-stats",
+		file1, file2, file3,
+	)
+	if err != nil {
+		t.Fatalf("runSCCWithStderr failed: %v\nstderr: %s", err, stderr)
+	}
+
+	statsRegex := regexp.MustCompile(`(?m)^bounded-memory: spills=(\d+) peak_in_memory_files=(\d+)$`)
+	matches := statsRegex.FindStringSubmatch(stderr)
+	if len(matches) != 3 {
+		t.Fatalf("expected bounded-memory stats line, got:\n%s", stderr)
+	}
+
+	spills, _ := strconv.Atoi(matches[1])
+	peak, _ := strconv.Atoi(matches[2])
+	if spills != 2 {
+		t.Fatalf("expected spills=2, got %d", spills)
+	}
+	if peak != 1 {
+		t.Fatalf("expected peak_in_memory_files=1, got %d", peak)
+	}
+
+	// Verify spill files exist on disk and are regular non-empty files
+	spillFile := filepath.Join(spillDir, "spill_1.jsonl")
+	info, err := os.Stat(spillFile)
+	if err != nil {
+		t.Fatalf("expected spill file %s to exist: %v", spillFile, err)
+	}
+	if info.Size() == 0 {
+		t.Fatalf("expected spill file %s to be non-empty", spillFile)
+	}
+	if !info.Mode().IsRegular() {
+		t.Fatalf("expected spill file %s to be regular file", spillFile)
+	}
+
+	// Test stats enabled without bounded-memory
+	_, stderrNoBound, err := runSCCWithStderr(
+		"--bounded-memory-stats",
+		file1,
+	)
+	if err != nil {
+		t.Fatalf("runSCCWithStderr failed: %v", err)
+	}
+	matchesNoBound := statsRegex.FindStringSubmatch(stderrNoBound)
+	if len(matchesNoBound) != 3 {
+		t.Fatalf("expected bounded-memory stats line when stats enabled without bounded-memory, got:\n%s", stderrNoBound)
+	}
+	if matchesNoBound[1] != "0" || matchesNoBound[2] != "0" {
+		t.Fatalf("expected spills=0 peak_in_memory_files=0, got %s", stderrNoBound)
+	}
+}
+
+func TestBoundedMemoryAutoCreateSpillDir(t *testing.T) {
+	tmpDir := t.TempDir()
