+func TestBoundedMemorySpillDirInsideScannedPath(t *testing.T) {
+	tmpDir := t.TempDir()
+	spillDir := filepath.Join(tmpDir, "spill_dir")
+	testFile := filepath.Join(tmpDir, "main.go")
