+	}
+
+	lines := strings.Split(strings.TrimSpace(string(content)), "\n")
+	if len(lines) < 2 {
+		t.Fatalf("expected multiple lines, got %d", len(lines))
+	}
+
+	var prevLines int64 = 1<<62 - 1
+	for idx, line := range lines[1:] {
+		parts := strings.Split(line, ",")
+		if len(parts) < 4 {
+			t.Fatalf("line %d malformed: %s", idx, line)
+		}
+		lineCount, err := strconv.ParseInt(parts[3], 10, 64)
+		if err != nil {
+			t.Fatalf("line %d invalid lines number: %s", idx, parts[3])
+		}
+		if lineCount > prevLines {
+			t.Fatalf("line %d: lines (%d) > prevLines (%d), not sorted descending!", idx, lineCount, prevLines)
+		}
+		prevLines = lineCount
+	}
+
+	// Sort by name
+	outFileName := filepath.Join(tmpDir, "sorted_name.csv")
+	_, stderr, err = runSCCWithStderr(
+		"--bounded-memory",
+		"--bounded-memory-dir", spillDir,
+		"--bounded-memory-max-in-memory-files", "2",
+		"--sort", "name",
+		"--format-multi", fmt.Sprintf("csv-stream:%s", outFileName),
+		"examples/language/",
+	)
+	if err != nil {
+		t.Fatalf("sort name run failed: %v\nstderr: %s", err, stderr)
+	}
+
+	contentName, err := os.ReadFile(outFileName)
+	if err != nil {
+		t.Fatalf("failed to read sorted name file: %v", err)
+	}
+	linesName := strings.Split(strings.TrimSpace(string(contentName)), "\n")
+	var prevName string
+	for idx, line := range linesName[1:] {
+		parts := strings.Split(line, ",")
+		if len(parts) < 3 {
+			t.Fatalf("line %d malformed: %s", idx, line)
+		}
+		name := parts[2]
+		if idx > 0 && name < prevName {
+			t.Fatalf("line %d: name (%s) < prevName (%s), not sorted ascending!", idx, name, prevName)
+		}
+		prevName = name
+	}
+}
+
+func TestBoundedMemoryTabularWideTotalsMatch(t *testing.T) {
+	tmpDir := t.TempDir()
+	spillDir := filepath.Join(tmpDir, "spill")
+
+	unboundedShort, err := runSCC("examples/language/")
+	if err != nil {
+		t.Fatalf("unbounded short failed: %v", err)
+	}
+	boundedShort, err := runSCC(
+		"--bounded-memory",
+		"--bounded-memory-dir", spillDir,
+		"--bounded-memory-max-in-memory-files", "2",
+		"examples/language/",
+	)
+	if err != nil {
+		t.Fatalf("bounded short failed: %v", err)
+	}
+
+	totalRegex := regexp.MustCompile(`(?m)^Total\s+.+$`)
+	unboundedTotal := totalRegex.FindString(unboundedShort)
+	boundedTotal := totalRegex.FindString(boundedShort)
+	if unboundedTotal != boundedTotal {
+		t.Fatalf("short Total line mismatch:\nUnbounded: %s\nBounded:   %s", unboundedTotal, boundedTotal)
+	}
+
+	// Wide
+	unboundedWide, err := runSCC("--format", "wide", "examples/language/")
+	if err != nil {
+		t.Fatalf("unbounded wide failed: %v", err)
+	}
+	boundedWide, err := runSCC(
+		"--bounded-memory",
+		"--bounded-memory-dir", spillDir,
+		"--bounded-memory-max-in-memory-files", "2",
+		"--format", "wide",
+		"examples/language/",
+	)
+	if err != nil {
+		t.Fatalf("bounded wide failed: %v", err)
+	}
+	unboundedWideTotal := totalRegex.FindString(unboundedWide)
+	boundedWideTotal := totalRegex.FindString(boundedWide)
+	if unboundedWideTotal != boundedWideTotal {
+		t.Fatalf("wide Total line mismatch:\nUnbounded: %s\nBounded:   %s", unboundedWideTotal, boundedWideTotal)
+	}
+}
