+// SPDX-License-Identifier: MIT
+
+package processor
+
+import (
+	"bufio"
+	"cmp"
+	"container/heap"
+	"encoding/json"
+	"fmt"
+	"io"
+	"os"
+	"path/filepath"
+	"regexp"
+	"slices"
+	"strings"
+
+	glanguage "golang.org/x/text/language"
+	gmessage "golang.org/x/text/message"
+)
+
+// SpilledFileJob is a lightweight representation of a processed FileJob for disk spilling.
+type SpilledFileJob struct {
+	Order              int     `json:"order"`
+	Language           string  `json:"l"`
+	Filename           string  `json:"f"`
+	Location           string  `json:"loc"`
+	Bytes              int64   `json:"b"`
+	Lines              int64   `json:"ln"`
+	Code               int64   `json:"c"`
+	Comment            int64   `json:"cm"`
+	Blank              int64   `json:"bl"`
+	Complexity         int64   `json:"cx"`
+	WeightedComplexity float64 `json:"wc"`
+	Uloc               int     `json:"u"`
+	LineLength         []int   `json:"ll,omitempty"`
+}
+
+func fileJobToSpilled(job *FileJob, order int) *SpilledFileJob {
+	return &SpilledFileJob{
+		Order:              order,
+		Language:           job.Language,
+		Filename:           job.Filename,
+		Location:           job.Location,
+		Bytes:              job.Bytes,
+		Lines:              job.Lines,
+		Code:               job.Code,
+		Comment:            job.Comment,
+		Blank:              job.Blank,
+		Complexity:         job.Complexity,
+		WeightedComplexity: job.WeightedComplexity,
+		Uloc:               job.Uloc,
+		LineLength:         job.LineLength,
+	}
+}
+
+func (s *SpilledFileJob) toFileJob() *FileJob {
+	return &FileJob{
+		Language:           s.Language,
+		Filename:           s.Filename,
+		Location:           s.Location,
+		Bytes:              s.Bytes,
+		Lines:              s.Lines,
+		Code:               s.Code,
+		Comment:            s.Comment,
+		Blank:              s.Blank,
+		Complexity:         s.Complexity,
+		WeightedComplexity: s.WeightedComplexity,
+		Uloc:               s.Uloc,
+		LineLength:         s.LineLength,
+	}
+}
+
+// RunReader defines an interface for stepping through a sorted or unsorted run of records.
+type RunReader interface {
+	Advance() bool
+	Current() *SpilledFileJob
+	Close() error
+}
+
+// DiskRunReader reads SpilledFileJob records line-by-line from a JSON Lines file.
+type DiskRunReader struct {
+	file    *os.File
+	scanner *bufio.Scanner
+	current *SpilledFileJob
+}
+
+func NewDiskRunReader(path string) (*DiskRunReader, error) {
+	f, err := os.Open(path)
+	if err != nil {
+		return nil, err
+	}
+	scanner := bufio.NewScanner(f)
+	buf := make([]byte, 1024*1024)
+	scanner.Buffer(buf, 64*1024*1024)
+	return &DiskRunReader{file: f, scanner: scanner}, nil
+}
+
+func (r *DiskRunReader) Advance() bool {
+	for r.scanner.Scan() {
+		line := r.scanner.Bytes()
+		if len(line) == 0 {
+			continue
+		}
+		var sj SpilledFileJob
+		if err := json.Unmarshal(line, &sj); err != nil {
+			return false
+		}
+		r.current = &sj
+		return true
+	}
+	return false
+}
+
+func (r *DiskRunReader) Current() *SpilledFileJob {
+	return r.current
+}
+
+func (r *DiskRunReader) Close() error {
+	if r.file != nil {
+		err := r.file.Close()
+		r.file = nil
+		return err
+	}
+	return nil
+}
+
+// MemoryRunReader steps through SpilledFileJob records stored in memory.
+type MemoryRunReader struct {
+	items []*SpilledFileJob
+	idx   int
+}
+
+func NewMemoryRunReader(items []*SpilledFileJob) *MemoryRunReader {
+	return &MemoryRunReader{items: items, idx: -1}
+}
+
+func (r *MemoryRunReader) Advance() bool {
+	r.idx++
+	return r.idx < len(r.items)
+}
+
+func (r *MemoryRunReader) Current() *SpilledFileJob {
+	return r.items[r.idx]
+}
+
+func (r *MemoryRunReader) Close() error {
+	return nil
+}
+
+type runItem struct {
+	reader  RunReader
+	current *SpilledFileJob
+}
+
+type runHeap struct {
+	items  []*runItem
+	sortBy string
+}
+
+func (h runHeap) Len() int { return len(h.items) }
+func (h runHeap) Less(i, j int) bool {
+	order := compareSpilledFileJob(h.items[i].current, h.items[j].current, h.sortBy)
+	if order != 0 {
+		return order < 0
+	}
+	return h.items[i].current.Order < h.items[j].current.Order
+}
+func (h runHeap) Swap(i, j int) { h.items[i], h.items[j] = h.items[j], h.items[i] }
+func (h *runHeap) Push(x any) {
+	h.items = append(h.items, x.(*runItem))
+}
+func (h *runHeap) Pop() any {
+	old := h.items
+	n := len(old)
+	x := old[n-1]
+	h.items = old[0 : n-1]
+	return x
+}
+
+func compareSpilledFileJob(a, b *SpilledFileJob, sortBy string) int {
+	switch strings.ToLower(sortBy) {
+	case "name", "names":
+		return strings.Compare(a.Filename, b.Filename)
+	case "language", "languages", "lang", "langs":
+		return strings.Compare(a.Language, b.Language)
+	case "line", "lines":
+		return cmp.Compare(b.Lines, a.Lines)
+	case "blank", "blanks":
+		return cmp.Compare(b.Blank, a.Blank)
+	case "code", "codes":
+		return cmp.Compare(b.Code, a.Code)
+	case "comment", "comments":
+		return cmp.Compare(b.Comment, a.Comment)
+	case "complexity", "complexitys", "comp":
+		return cmp.Compare(b.Complexity, a.Complexity)
+	case "byte", "bytes":
+		return cmp.Compare(b.Bytes, a.Bytes)
+	case "uloc":
+		return cmp.Compare(b.Uloc, a.Uloc)
+	default:
+		return strings.Compare(a.Filename, b.Filename)
+	}
+}
+
+func isSortingRequested() bool {
+	return SortBySet || (SortBy != "" && strings.ToLower(SortBy) != "files")
+}
+
+// BoundedMemorySpiller manages buffering and spilling of file jobs to stay within configured limits.
+type BoundedMemorySpiller struct {
+	dir               string
+	maxFiles          int
+	spills            int
+	peakInMemoryFiles int
+	spillFiles        []string
+	buffer            []*SpilledFileJob
+	totalFiles        int
+	mergeFilesCount   int
+}
+
+func NewBoundedMemorySpiller(dir string, maxFiles int) *BoundedMemorySpiller {
+	return &BoundedMemorySpiller{
+		dir:      dir,
+		maxFiles: maxFiles,
+		buffer:   make([]*SpilledFileJob, 0, maxFiles),
+	}
+}
+
+func (s *BoundedMemorySpiller) Add(job *FileJob) error {
+	if len(s.buffer) >= s.maxFiles {
+		if err := s.spill(); err != nil {
+			return err
+		}
+	}
+	sJob := fileJobToSpilled(job, s.totalFiles)
+	s.buffer = append(s.buffer, sJob)
+	s.totalFiles++
+	if len(s.buffer) > s.peakInMemoryFiles {
+		s.peakInMemoryFiles = len(s.buffer)
+	}
+	return nil
+}
+
+func (s *BoundedMemorySpiller) spill() error {
+	s.spills++
+	spillPath := filepath.Join(s.dir, fmt.Sprintf("spill_%d.jsonl", s.spills))
+	f, err := os.OpenFile(spillPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644)
+	if err != nil {
+		return err
+	}
+	w := bufio.NewWriter(f)
+
+	if isSortingRequested() {
+		slices.SortStableFunc(s.buffer, func(a, b *SpilledFileJob) int {
+			if order := compareSpilledFileJob(a, b, SortBy); order != 0 {
+				return order
+			}
+			return cmp.Compare(a.Order, b.Order)
+		})
+	}
+
+	for _, item := range s.buffer {
+		data, err := json.Marshal(item)
+		if err != nil {
+			_ = f.Close()
+			return err
+		}
+		if _, err := w.Write(data); err != nil {
+			_ = f.Close()
+			return err
+		}
+		if err := w.WriteByte('\n'); err != nil {
+			_ = f.Close()
+			return err
+		}
+	}
+	if err := w.Flush(); err != nil {
+		_ = f.Close()
+		return err
+	}
+	if err := f.Close(); err != nil {
+		return err
+	}
+
+	s.spillFiles = append(s.spillFiles, spillPath)
+	s.buffer = make([]*SpilledFileJob, 0, s.maxFiles)
+	return nil
+}
+
+func (s *BoundedMemorySpiller) Finish() {
+	if len(s.buffer) > s.peakInMemoryFiles {
+		s.peakInMemoryFiles = len(s.buffer)
+	}
+	if isSortingRequested() && len(s.buffer) > 0 {
+		slices.SortStableFunc(s.buffer, func(a, b *SpilledFileJob) int {
+			if order := compareSpilledFileJob(a, b, SortBy); order != 0 {
+				return order
+			}
+			return cmp.Compare(a.Order, b.Order)
+		})
+	}
+}
+
+func (s *BoundedMemorySpiller) ForEach(fn func(job *FileJob) error) error {
+	for _, fpath := range s.spillFiles {
+		f, err := os.Open(fpath)
+		if err != nil {
+			return err
+		}
+		scanner := bufio.NewScanner(f)
+		buf := make([]byte, 1024*1024)
+		scanner.Buffer(buf, 64*1024*1024)
+		for scanner.Scan() {
+			line := scanner.Bytes()
+			if len(line) == 0 {
+				continue
+			}
+			var sj SpilledFileJob
+			if err := json.Unmarshal(line, &sj); err != nil {
+				_ = f.Close()
+				return err
+			}
+			if err := fn(sj.toFileJob()); err != nil {
+				_ = f.Close()
+				return err
+			}
+		}
+		_ = f.Close()
+		if err := scanner.Err(); err != nil {
+			return err
+		}
+	}
+
+	for _, sj := range s.buffer {
+		if err := fn(sj.toFileJob()); err != nil {
+			return err
+		}
+	}
+
+	return nil
+}
+
+func (s *BoundedMemorySpiller) ReplayChannel() chan *FileJob {
+	ch := make(chan *FileJob, 1)
+	go func() {
+		defer close(ch)
+		_ = s.ForEach(func(job *FileJob) error {
+			ch <- job
+			return nil
+		})
+	}()
+	return ch
+}
+
+func (s *BoundedMemorySpiller) WriteCSVStream(w io.Writer) error {
+	quoteRegex := regexp.MustCompile("\"")
+	bw := bufio.NewWriter(w)
+	defer bw.Flush()
+
+	if _, err := bw.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n"); err != nil {
+		return err
+	}
+
+	if !isSortingRequested() {
+		return s.ForEach(func(job *FileJob) error {
+			location := "\"" + quoteRegex.ReplaceAllString(job.Location, "\"\"") + "\""
+			filename := "\"" + quoteRegex.ReplaceAllString(job.Filename, "\"\"") + "\""
+			_, err := fmt.Fprintf(bw, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
+				job.Language,
+				location,
+				filename,
+				job.Lines,
+				job.Code,
+				job.Comment,
+				job.Blank,
+				job.Complexity,
+				job.Bytes,
+				job.Uloc,
+			)
+			return err
+		})
+	}
+
+	if len(s.spillFiles) == 0 {
+		for _, item := range s.buffer {
+			location := "\"" + quoteRegex.ReplaceAllString(item.Location, "\"\"") + "\""
+			filename := "\"" + quoteRegex.ReplaceAllString(item.Filename, "\"\"") + "\""
+			if _, err := fmt.Fprintf(bw, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
+				item.Language,
+				location,
+				filename,
+				item.Lines,
+				item.Code,
+				item.Comment,
+				item.Blank,
+				item.Complexity,
+				item.Bytes,
+				item.Uloc,
+			); err != nil {
+				return err
+			}
+		}
+		return nil
+	}
+
+	return s.externalMergeSortCSVStream(bw, quoteRegex)
+}
+
+func (s *BoundedMemorySpiller) externalMergeSortCSVStream(bw *bufio.Writer, quoteRegex *regexp.Regexp) error {
+	diskFiles := append([]string{}, s.spillFiles...)
+	for len(diskFiles) > 63 {
+		batchSize := 63
+		if len(diskFiles) < batchSize {
+			batchSize = len(diskFiles)
+		}
+		batch := diskFiles[:batchSize]
+		diskFiles = diskFiles[batchSize:]
+
+		mergedFile, err := s.mergeDiskRuns(batch)
+		if err != nil {
+			return err
+		}
+		diskFiles = append(diskFiles, mergedFile)
+	}
+
+	readers := make([]RunReader, 0, len(diskFiles)+1)
+	for _, df := range diskFiles {
+		dr, err := NewDiskRunReader(df)
+		if err != nil {
+			for _, r := range readers {
+				_ = r.Close()
+			}
+			return err
+		}
+		readers = append(readers, dr)
+	}
+	if len(s.buffer) > 0 {
+		readers = append(readers, NewMemoryRunReader(s.buffer))
+	}
+
+	h := &runHeap{sortBy: SortBy}
+	for _, r := range readers {
+		if r.Advance() {
+			h.items = append(h.items, &runItem{reader: r, current: r.Current()})
+		} else {
+			_ = r.Close()
+		}
+	}
+	heap.Init(h)
+
+	for h.Len() > 0 {
+		item := heap.Pop(h).(*runItem)
+		job := item.current
+		location := "\"" + quoteRegex.ReplaceAllString(job.Location, "\"\"") + "\""
+		filename := "\"" + quoteRegex.ReplaceAllString(job.Filename, "\"\"") + "\""
+		if _, err := fmt.Fprintf(bw, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
+			job.Language,
+			location,
+			filename,
+			job.Lines,
+			job.Code,
+			job.Comment,
+			job.Blank,
+			job.Complexity,
+			job.Bytes,
+			job.Uloc,
+		); err != nil {
+			for _, it := range h.items {
+				_ = it.reader.Close()
+			}
+			return err
+		}
+
+		if item.reader.Advance() {
+			item.current = item.reader.Current()
+			heap.Push(h, item)
+		} else {
+			_ = item.reader.Close()
+		}
+	}
+
+	return nil
+}
+
+func (s *BoundedMemorySpiller) mergeDiskRuns(files []string) (string, error) {
+	s.mergeFilesCount++
+	outPath := filepath.Join(s.dir, fmt.Sprintf("merge_%d.jsonl", s.mergeFilesCount))
+	outFile, err := os.OpenFile(outPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644)
+	if err != nil {
+		return "", err
+	}
+	bw := bufio.NewWriter(outFile)
+
+	readers := make([]RunReader, 0, len(files))
+	for _, f := range files {
+		dr, err := NewDiskRunReader(f)
+		if err != nil {
+			for _, r := range readers {
+				_ = r.Close()
+			}
+			_ = outFile.Close()
+			return "", err
+		}
+		readers = append(readers, dr)
+	}
+
+	h := &runHeap{sortBy: SortBy}
+	for _, r := range readers {
+		if r.Advance() {
+			h.items = append(h.items, &runItem{reader: r, current: r.Current()})
+		} else {
+			_ = r.Close()
+		}
+	}
+	heap.Init(h)
+
+	for h.Len() > 0 {
+		item := heap.Pop(h).(*runItem)
+		data, err := json.Marshal(item.current)
+		if err != nil {
+			_ = outFile.Close()
+			return "", err
+		}
+		if _, err := bw.Write(data); err != nil {
+			_ = outFile.Close()
+			return "", err
+		}
+		if err := bw.WriteByte('\n'); err != nil {
+			_ = outFile.Close()
+			return "", err
+		}
+
+		if item.reader.Advance() {
+			item.current = item.reader.Current()
+			heap.Push(h, item)
+		} else {
+			_ = item.reader.Close()
+		}
+	}
+
+	if err := bw.Flush(); err != nil {
+		_ = outFile.Close()
+		return "", err
+	}
+	if err := outFile.Close(); err != nil {
+		return "", err
+	}
+	return outPath, nil
+}
+
+func (s *BoundedMemorySpiller) ToTabularShort() string {
+	str := &strings.Builder{}
+
+	str.WriteString(getTabularShortBreak())
+	if !Complexity {
+		_, _ = fmt.Fprintf(str, tabularShortFormatHead, "Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity")
+	} else {
+		_, _ = fmt.Fprintf(str, tabularShortFormatHeadNoComplexity, "Language", "Files", "Lines", "Blanks", "Comments", "Code")
+	}
+
+	if !Files {
+		str.WriteString(getTabularShortBreak())
+	}
+
+	lang := map[string]LanguageSummary{}
+	var sumFiles, sumLines, sumCode, sumComment, sumBlank, sumComplexity, sumBytes int64
+
+	p := gmessage.NewPrinter(glanguage.Make(os.Getenv("LANG")))
+
+	_ = s.ForEach(func(res *FileJob) error {
+		sumFiles++
+		sumLines += res.Lines
+		sumCode += res.Code
+		sumComment += res.Comment
+		sumBlank += res.Blank
+		sumComplexity += res.Complexity
+		sumBytes += res.Bytes
+
+		_, ok := lang[res.Language]
+
+		if !ok {
+			var files []*FileJob
+			if Files {
+				files = []*FileJob{res}
+			}
+
+			lang[res.Language] = LanguageSummary{
+				Name:       res.Language,
+				Lines:      res.Lines,
+				Code:       res.Code,
+				Comment:    res.Comment,
+				Blank:      res.Blank,
+				Complexity: res.Complexity,
+				Count:      1,
+				Files:      files,
+				LineLength: res.LineLength,
+			}
+		} else {
+			tmp := lang[res.Language]
+			var files []*FileJob
+			if Files {
+				files = append(tmp.Files, res)
+			}
+			var lineLength []int
+			if MaxMean {
+				lineLength = append(tmp.LineLength, res.LineLength...)
+			}
+
+			lang[res.Language] = LanguageSummary{
+				Name:       res.Language,
+				Lines:      tmp.Lines + res.Lines,
+				Code:       tmp.Code + res.Code,
+				Comment:    tmp.Comment + res.Comment,
+				Blank:      tmp.Blank + res.Blank,
+				Complexity: tmp.Complexity + res.Complexity,
+				Count:      tmp.Count + 1,
+				Files:      files,
+				LineLength: lineLength,
+			}
+		}
+		return nil
+	})
+
+	language := make([]LanguageSummary, 0, len(lang))
+	for _, summary := range lang {
+		language = append(language, summary)
+	}
+
+	language = sortLanguageSummary(language)
+
+	startTime := makeTimestampMilli()
+	for _, summary := range language {
+		addBreak := false
+		if Files {
+			str.WriteString(getTabularShortBreak())
+		}
+
+		trimmedName := summary.Name
+		trimmedName = trimNameShort(summary, trimmedName)
+
+		if !Complexity {
+			_, _ = p.Fprintf(str, tabularShortFormatBody, trimmedName, summary.Count, summary.Lines, summary.Blank, summary.Comment, summary.Code, summary.Complexity)
+		} else {
+			_, _ = p.Fprintf(str, tabularShortFormatBodyNoComplexity, trimmedName, summary.Count, summary.Lines, summary.Blank, summary.Comment, summary.Code)
+		}
+
+		if Percent {
+			if !Complexity {
+				_, _ = p.Fprintf(str,
+					tabularShortPercentLanguageFormatBody,
+					float64(summary.Count)/float64(sumFiles)*100,
+					float64(summary.Lines)/float64(sumLines)*100,
+					float64(summary.Blank)/float64(sumBlank)*100,
+					float64(summary.Comment)/float64(sumComment)*100,
+					float64(summary.Code)/float64(sumCode)*100,
+					float64(summary.Complexity)/float64(sumComplexity)*100,
+				)
+			} else {
+				_, _ = p.Fprintf(str,
+					tabularShortPercentLanguageFormatBodyNoComplexity,
+					float64(summary.Count)/float64(sumFiles)*100,
+					float64(summary.Lines)/float64(sumLines)*100,
+					float64(summary.Blank)/float64(sumBlank)*100,
+					float64(summary.Comment)/float64(sumComment)*100,
+					float64(summary.Code)/float64(sumCode)*100,
+				)
+			}
+
+			addBreak = true
+		}
+
+		if MaxMean {
+			if !Complexity {
+				_, _ = p.Fprintf(str, tabularShortFormatFileMaxMean, maxIn(summary.LineLength), meanIn(summary.LineLength))
+			} else {
+				_, _ = p.Fprintf(str, tabularShortFormatFileMaxMeanNoComplexity, maxIn(summary.LineLength), meanIn(summary.LineLength))
+			}
+
+			addBreak = true
+		}
+
+		if Files {
+			sortSummaryFiles(&summary)
+			str.WriteString(getTabularShortBreak())
+
+			for _, res := range summary.Files {
+				tmp := unicodeAwareTrim(res.Location, shortFormatFileTruncate)
+
+				if !Complexity {
+					tmp = unicodeAwareRightPad(tmp, 27)
+					_, _ = p.Fprintf(str, tabularShortFormatFile, tmp, res.Lines, res.Blank, res.Comment, res.Code, res.Complexity)
+				} else {
+					tmp = unicodeAwareRightPad(tmp, 34)
+					_, _ = p.Fprintf(str, tabularShortFormatFileNoComplexity, tmp, res.Lines, res.Blank, res.Comment, res.Code)
+				}
+			}
+		}
+
+		if UlocMode {
+			if !Complexity {
+				_, _ = p.Fprintf(str, tabularShortUlocLanguageFormatBody, len(ulocLanguageCount[summary.Name]))
+			} else {
+				_, _ = p.Fprintf(str, tabularShortUlocLanguageFormatBodyNoComplexity, len(ulocLanguageCount[summary.Name]))
+			}
+
+			addBreak = true
+		}
+
+		if addBreak {
+			if !Files && summary.Name != language[len(language)-1].Name {
+				str.WriteString(tabularShortBreakCi)
+			}
+		}
+	}
+
+	printDebugF("milliseconds to build formatted string: %d", makeTimestampMilli()-startTime)
+
+	str.WriteString(getTabularShortBreak())
+	if !Complexity {
+		_, _ = p.Fprintf(str, tabularShortFormatBody, "Total", sumFiles, sumLines, sumBlank, sumComment, sumCode, sumComplexity)
+	} else {
+		_, _ = p.Fprintf(str, tabularShortFormatBodyNoComplexity, "Total", sumFiles, sumLines, sumBlank, sumComment, sumCode)
+	}
+	str.WriteString(getTabularShortBreak())
+
+	if UlocMode {
+		_, _ = p.Fprintf(str, tabularShortUlocGlobalFormatBody, len(ulocGlobalCount))
+		if Dryness {
+			dryness := float64(len(ulocGlobalCount)) / float64(sumLines)
+			_, _ = p.Fprintf(str, tabularShortDrynessFormatBody, dryness)
+		}
+		str.WriteString(getTabularShortBreak())
+	}
+
+	if !Cocomo {
+		if SLOCCountFormat {
+			calculateCocomoSLOCCount(sumCode, str)
+		} else {
+			calculateCocomo(sumCode, str)
+		}
+		str.WriteString(getTabularShortBreak())
+	}
+	if Locomo {
+		calculateLocomo(sumCode, sumComplexity, str)
+		str.WriteString(getTabularShortBreak())
+	}
+	if !Size {
+		calculateSize(sumBytes, str)
+		str.WriteString(getTabularShortBreak())
+	}
+
+	return str.String()
+}
