+func fileSummarizeBounded(input chan *FileJob) string {
+	spiller := NewBoundedMemorySpiller(BoundedMemoryDir, BoundedMemoryMaxInMemoryFiles)
+	for job := range input {
+		if err := spiller.Add(job); err != nil {
+			printError(fmt.Sprintf("bounded memory error: %s", err))
+		}
+	}
+	spiller.Finish()
+
+	var result string
+	if FormatMulti == "" {
+		switch {
+		case More || strings.EqualFold(Format, "wide"):
+			result = spiller.ToTabularLong()
+		case strings.EqualFold(Format, "json"):
+			result = toJSON(spiller.ReplayChannel())
+		case strings.EqualFold(Format, "json2"):
+			result = toJSON2(spiller.ReplayChannel())
+		case strings.EqualFold(Format, "cloc-yaml") || strings.EqualFold(Format, "cloc-yml"):
+			result = toClocYAML(spiller.ReplayChannel())
+		case strings.EqualFold(Format, "csv"):
+			result = toCSV(spiller.ReplayChannel())
+		case strings.EqualFold(Format, "csv-stream"):
+			var buf strings.Builder
+			_ = spiller.WriteCSVStream(&buf)
+			result = buf.String()
+		case strings.EqualFold(Format, "html"):
+			result = toHtml(spiller.ReplayChannel())
+		case strings.EqualFold(Format, "html-table"):
+			result = toHtmlTable(spiller.ReplayChannel())
+		case strings.EqualFold(Format, "sql"):
+			result = toSql(spiller.ReplayChannel())
+		case strings.EqualFold(Format, "sql-insert"):
+			result = toSqlInsert(spiller.ReplayChannel())
+		case strings.EqualFold(Format, "openmetrics"):
+			result = toOpenMetrics(spiller.ReplayChannel())
+		default:
+			result = spiller.ToTabularShort()
+		}
+	} else {
+		var str strings.Builder
+
+		for _, s := range strings.Split(FormatMulti, ",") {
+			t := strings.Split(s, ":")
+			format := strings.ToLower(t[0])
+			target := "stdout"
+			if len(t) > 1 {
+				target = strings.Join(t[1:], ":")
+			}
+
+			if format == "csv-stream" {
+				if target == "stdout" {
+					var buf strings.Builder
+					_ = spiller.WriteCSVStream(&buf)
+					str.WriteString(buf.String())
+				} else {
+					f, err := os.OpenFile(target, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
+					if err != nil {
+						fmt.Printf("%s unable to be written to for format %s: %s\n", target, format, err)
+					} else {
+						err := spiller.WriteCSVStream(f)
+						_ = f.Close()
+						if err != nil {
+							fmt.Printf("%s unable to be written to for format %s: %s\n", target, format, err)
+						}
+					}
+				}
+				continue
+			}
+
+			var val string
+			switch format {
+			case "tabular":
+				val = spiller.ToTabularShort()
+			case "wide":
+				val = spiller.ToTabularLong()
+			case "json":
+				val = toJSON(spiller.ReplayChannel())
+			case "json2":
+				val = toJSON2(spiller.ReplayChannel())
+			case "csv":
+				val = toCSV(spiller.ReplayChannel())
+			case "cloc-yaml", "cloc-yml":
+				val = toClocYAML(spiller.ReplayChannel())
+			case "html":
+				val = toHtml(spiller.ReplayChannel())
+			case "html-table":
+				val = toHtmlTable(spiller.ReplayChannel())
+			case "sql":
+				val = toSql(spiller.ReplayChannel())
+			case "sql-insert":
+				val = toSqlInsert(spiller.ReplayChannel())
+			case "openmetrics":
+				val = toOpenMetrics(spiller.ReplayChannel())
+			default:
+				val = spiller.ToTabularShort()
+			}
+
+			if target == "stdout" {
+				str.WriteString(val)
+				str.WriteString("\n")
+			} else {
+				err := os.WriteFile(target, []byte(val), 0600)
+				if err != nil {
+					fmt.Printf("%s unable to be written to for format %s: %s\n", target, format, err)
+				}
+			}
+		}
+		result = str.String()
+	}
+
+	if BoundedMemoryStats {
+		fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", spiller.spills, spiller.peakInMemoryFiles)
+	}
+
+	return result
+}
+
+func isPathInsideOrEqual(path, targetDir string) bool {
+	if path == "" || targetDir == "" {
+		return false
+	}
+	absPath, err := filepath.Abs(path)
+	if err != nil {
+		absPath = path
+	} else if eval, err := filepath.EvalSymlinks(absPath); err == nil {
+		absPath = eval
+	}
+
+	absTarget, err := filepath.Abs(targetDir)
+	if err != nil {
+		absTarget = targetDir
+	} else if eval, err := filepath.EvalSymlinks(absTarget); err == nil {
+		absTarget = eval
+	}
+
+	rel, err := filepath.Rel(absTarget, absPath)
+	if err != nil {
+		return false
+	}
+	return rel == "." || (!strings.HasPrefix(rel, "..") && !filepath.IsAbs(rel))
+}
